static bool read_PersistentRoadSamples(Buffer* buffer, STI_TypeLibrary* lib, PersistentRoadSamples* out) {
    if (!read_DynamicArray_PatchSampleList(buffer, lib, &out->Patches)) return false;
    if (!read_DynamicArray_STI_uint16(buffer, lib, &out->SampleIndices)) return false;
    return true;
}
static void free_PersistentRoadSamples(PersistentRoadSamples* obj, STI_TypeLibrary* lib) {
    free_DynamicArray_PatchSampleList(&obj->Patches, lib);
    free_DynamicArray_STI_uint16(&obj->SampleIndices, lib);
}
static void print_PersistentRoadSamples(const PersistentRoadSamples* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "PersistentRoadSamples {\n");
    indent++;
    fprintf(handle, "%*s%s = ", indent * 4, "", "Patches");
    print_DynamicArray_PatchSampleList(&obj->Patches, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "SampleIndices");
    print_DynamicArray_STI_uint16(&obj->SampleIndices, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s}", (indent - 1)*4, "");
}
