    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainDisplacementTexture");
    print_TerrainTexture(&obj->TerrainDisplacementTexture, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainNormalTexture");
    print_TerrainTexture(&obj->TerrainNormalTexture, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainTriangleMapTexture");
    print_TerrainTexture(&obj->TerrainTriangleMapTexture, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainMaterialDuplexTexture");
    print_TerrainTexture(&obj->TerrainMaterialDuplexTexture, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainColorTexture");
    print_TerrainTexture(&obj->TerrainColorTexture, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainQualityTexture");
    print_TerrainTexture(&obj->TerrainQualityTexture, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainIndirectionTexture");
    print_TerrainTexture(&obj->TerrainIndirectionTexture, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "TerrainSSDFAtlas");
