static bool read_BarkConstants(Buffer* buffer, STI_TypeLibrary* lib, BarkConstants* out) {
    if (!read_STI_float32(buffer, lib, &out->Glossiness)) return false;
    if (!read_STI_float32(buffer, lib, &out->NormalStrength)) return false;
    if (!read_STI_float32(buffer, lib, &out->DiffuseWrap)) return false;
    if (!read_STI_float32(buffer, lib, &out->Fresnel)) return false;
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DiffuseModulator[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->LayeredHeightMapUVScale)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredUVScale)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredHeight1Influence)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredHeight2Influence)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredHeightMapInfluence)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredMaskInfluence)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredShift)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredRoughness)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredDiffuseWrap)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredEmissive)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredTransmission)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredReflectivity)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredClearCoat)) return false;
    if (!read_STI_float32(buffer, lib, &out->LayeredUpInfluence)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayHeightInfluence)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayHeightMapInfluence)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayMaskInfluence)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayShift)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->OverlayColor[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->OverlayBrightness)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayGloss)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayMetallic)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayReflectivity)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayRoughness)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayDiffuseWrap)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayEmissive)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayTransmission)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayClearCoat)) return false;
    if (!read_STI_float32(buffer, lib, &out->OverlayUpInfluence)) return false;
{
        uint8 bitfield_value = 0;
        if (!read_STI_uint8(buffer, lib, &bitfield_value)) return false;
        out->NoFade = (bitfield_value >> 0) & 0x1;
        out->UseWaterFog = (bitfield_value >> 1) & 0x1;
        out->LowResShadows = (bitfield_value >> 2) & 0x1;
        out->UseLayered = (bitfield_value >> 3) & 0x1;
        out->UseOverlay = (bitfield_value >> 4) & 0x1;
        out->IgnoreColorTint = (bitfield_value >> 5) & 0x1;
}
    buffer->skip(buffer, 3);
    return true;
}
