    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "y_min");
    print_STI_float32(&obj->y_min, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "y_max");
    print_STI_float32(&obj->y_max, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "interpolation_type");
    print_STI_int8(&obj->interpolation_type, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "number_of_control_points");
    print_STI_int8(&obj->number_of_control_points, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "control_points");
    fprintf(handle, "{\n%*s", (indent+1)*4, "");
    for (uint32 i = 0; i < 20; ++i) {
        print_SplineControlPoint(&obj->control_points[i], lib, handle, indent+1);
        if(i < 19){
            fprintf(handle,", \n%*s", (indent+1)*4, "");
        }
    }
    fprintf(handle, "\n%*s}", (indent+1)*4, "");
    fprintf(handle, "\n");
    fprintf(handle, "%*s}", (indent - 1)*4, "");
