    buffer->skip(buffer, -8);
    if (!read_STI_String(buffer, lib, &out->BuildTime)) return false;
    buffer->skip(buffer, -8);
    if (!read_DynamicArray_Shader(buffer, lib, &out->VertexShaders)) return false;
    if (!read_DynamicArray_Shader(buffer, lib, &out->FragmentShaders)) return false;
    if (!read_DynamicArray_Shader(buffer, lib, &out->ComputeShaders)) return false;
    if (!read_DynamicArray_Shader(buffer, lib, &out->GeometryShaders)) return false;
    if (!read_DynamicArray_Shader(buffer, lib, &out->HullShaders)) return false;
    if (!read_DynamicArray_Shader(buffer, lib, &out->DomainShaders)) return false;
    return true;
