static bool read_SchematicTreeNode(Buffer* buffer, STI_TypeLibrary* lib, SchematicTreeNode* out) {
    if (!read_STI_uint32(buffer, lib, &out->EquipmentHash)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Currency)) return false;
    if (!read_STI_int32(buffer, lib, &out->UnlockCost)) return false;
{
        uint8 bitfield_value = 0;
        if (!read_STI_uint8(buffer, lib, &bitfield_value)) return false;
        out->ConsumeCost = (bitfield_value >> 0) & 0x1;
}
    buffer->skip(buffer, 1);
    for (uint32 i = 0; i < 8; ++i) {
        if (!read_STI_uint16(buffer, lib, &out->Prerequisites[i])) return false;
    }
    for (uint32 i = 0; i < 8; ++i) {
        if (!read_STI_uint16(buffer, lib, &out->Children[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->DisplayMode)) return false;
    buffer->skip(buffer, 1);
    return true;
}
