    if (!read_STI_float32(buffer, lib, &out->MaxSpeed)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxDeltaDolly)) return false;
    if (!read_CameraSpring(buffer, lib, &out->DollySpring)) return false;
