static bool read_LandGlobal(Buffer* buffer, STI_TypeLibrary* lib, LandGlobal* out) {
    if (!read_STI_int32(buffer, lib, &out->number_of_wheels)) return false;
    if (!read_STI_int32(buffer, lib, &out->number_of_front_wheels)) return false;
    if (!read_STI_int8(buffer, lib, &out->is_rear_steered)) return false;
    if (!read_STI_int8(buffer, lib, &out->is_all_wheel_steered)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_int32(buffer, lib, &out->wheels_friction_type)) return false;
    if (!read_STI_float32(buffer, lib, &out->normal_clipping_angle_cosine)) return false;
    if (!read_STI_float32(buffer, lib, &out->ground_clearance)) return false;
    if (!read_LandWheel(buffer, lib, &out->front_wheels)) return false;
    if (!read_LandWheel(buffer, lib, &out->rear_wheels)) return false;
    if (!read_DynamicArray_WheelHardpoint(buffer, lib, &out->base_wheel_hardpoint_positions)) return false;
    return true;
}
