static bool read_VegetationModel(Buffer* buffer, STI_TypeLibrary* lib, VegetationModel* out) {
    if (!read_STI_uint16(buffer, lib, &out->ModelIndex)) return false;
    if (!read_STI_uint16(buffer, lib, &out->ModelHandle)) return false;
    if (!read_STI_uint16(buffer, lib, &out->ModelExtraLodsHandle)) return false;
    if (!read_STI_uint8(buffer, lib, &out->ShadowCascadeLimit)) return false;
    if (!read_STI_int8(buffer, lib, &out->LodCount)) return false;
    if (!read_STI_float32(buffer, lib, &out->LodFactor)) return false;
    if (!read_STI_float32(buffer, lib, &out->LodBias)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->HalfExtents[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->ForestColor[i])) return false;
    }
    buffer->skip(buffer, 1);
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->ModelFilenameHash)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->ModelExtraLodsFilenameHash)) return false;
    if (!read_STI_float32(buffer, lib, &out->TerrainColoringFactor)) return false;
    if (!read_STI_int16(buffer, lib, &out->Impostor)) return false;
    if (!read_STI_uint8(buffer, lib, &out->UseBillboard)) return false;
    if (!read_STI_uint8(buffer, lib, &out->FarLayer)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->BillboardSize[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SwayFactor)) return false;
    if (!read_STI_uint8(buffer, lib, &out->GlobalIlluminationMask)) return false;
    if (!read_STI_uint8(buffer, lib, &out->AlphaBlendLodMask)) return false;
    if (!read_STI_uint8(buffer, lib, &out->AlphaFadeLodMask)) return false;
    for (uint32 i = 0; i < 5; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->AlphaThreshold[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->AlphaMultiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->NormalFadeDistance)) return false;
    if (!read_STI_float32(buffer, lib, &out->NormalBendNear)) return false;
    if (!read_STI_float32(buffer, lib, &out->NormalBendFar)) return false;
    if (!read_STI_float32(buffer, lib, &out->SphereNormalFadeInStart)) return false;
    if (!read_STI_float32(buffer, lib, &out->SphereNormalFadeInEnd)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Flags)) return false;
    return true;
}
