static bool read_Transmission(Buffer* buffer, STI_TypeLibrary* lib, Transmission* out) {
    if (!read_STI_int32(buffer, lib, &out->gears)) return false;
    if (!read_STI_int32(buffer, lib, &out->nitrous_gears)) return false;
    for (uint32 i = 0; i < 8; ++i) {
        if (!read_STI_float32(buffer, lib, &out->gear_ratios[i])) return false;
    }
    for (uint32 i = 0; i < 8; ++i) {
        if (!read_STI_float32(buffer, lib, &out->upshift_rpm[i])) return false;
    }
    for (uint32 i = 0; i < 8; ++i) {
        if (!read_STI_float32(buffer, lib, &out->downshift_rpm[i])) return false;
    }
    if (!read_STI_int32(buffer, lib, &out->sequential)) return false;
    if (!read_STI_int32(buffer, lib, &out->manual_clutch)) return false;
    if (!read_STI_float32(buffer, lib, &out->manual_clutch_blend_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->manual_clutch_blend_time)) return false;
    if (!read_STI_float32(buffer, lib, &out->forward_ratio_percentage)) return false;
    if (!read_STI_float32(buffer, lib, &out->low_gear_forward_ratio_pct)) return false;
    if (!read_STI_float32(buffer, lib, &out->top_speed)) return false;
    if (!read_STI_float32(buffer, lib, &out->low_gears_final_drive)) return false;
    if (!read_STI_float32(buffer, lib, &out->final_drive)) return false;
    if (!read_STI_int32(buffer, lib, &out->reverse_uses_forward_gears)) return false;
    if (!read_STI_float32(buffer, lib, &out->reverse_gear_ratio)) return false;
    if (!read_STI_float32(buffer, lib, &out->clutch_delay)) return false;
    if (!read_STI_float32(buffer, lib, &out->decay_time_to_cruise_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->target_cruise_rpm)) return false;
    return true;
}
