static bool read_VegetationPhysics(Buffer* buffer, STI_TypeLibrary* lib, VegetationPhysics* out) {
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->PfxFile)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->NavmeshPfxFile)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->StumpFile)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->PfxStumpFile)) return false;
    if (!read_DynamicArray_StringHash_48c5294d_4(buffer, lib, &out->BrokenFile)) return false;
    if (!read_DynamicArray_StringHash_48c5294d_4(buffer, lib, &out->BrokenPfxFile)) return false;
    if (!read_STI_uint16(buffer, lib, &out->PhysicsHandle)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_float32(buffer, lib, &out->ImpulseLimitPassThrough)) return false;
    if (!read_STI_float32(buffer, lib, &out->ImpulseThreshold)) return false;
    if (!read_STI_float32(buffer, lib, &out->BreakByBulletLimit)) return false;
    if (!read_STI_float32(buffer, lib, &out->BreakByExplosionLimit)) return false;
    if (!read_STI_float32(buffer, lib, &out->ExplosiveImpulseModifier)) return false;
    if (!read_STI_float32(buffer, lib, &out->AngularLimit)) return false;
    if (!read_STI_float32(buffer, lib, &out->Magnitude)) return false;
{
        uint8 bitfield_value = 0;
        if (!read_STI_uint8(buffer, lib, &bitfield_value)) return false;
        out->BreaksOnCollision = (bitfield_value >> 0) & 0x1;
        out->TerrainNormal = (bitfield_value >> 1) & 0x1;
        out->HasCollisions = (bitfield_value >> 2) & 0x1;
        out->FarModel = (bitfield_value >> 3) & 0x1;
        out->IsPebble = (bitfield_value >> 4) & 0x1;
        out->IgnorePlayer = (bitfield_value >> 5) & 0x1;
        out->IsAiCover = (bitfield_value >> 6) & 0x1;
}
    if (!read_STI_uint8(buffer, lib, &out->StaticPathfinding)) return false;
    if (!read_STI_uint8(buffer, lib, &out->NavmeshUseHull2d)) return false;
    buffer->skip(buffer, 5);
    return true;
}
