static bool read_CharacterConstants(Buffer* buffer, STI_TypeLibrary* lib, CharacterConstants* out) {
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DetailTilingFactorUV[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SpecularGloss)) return false;
    if (!read_STI_float32(buffer, lib, &out->TransmissionIntensity)) return false;
    if (!read_STI_float32(buffer, lib, &out->DiffuseRoughness)) return false;
    if (!read_STI_float32(buffer, lib, &out->EmissiveIntensity)) return false;
    if (!read_STI_float32(buffer, lib, &out->NightVisibility)) return false;
    if (!read_STI_float32(buffer, lib, &out->RimFrontStrength)) return false;
    if (!read_STI_float32(buffer, lib, &out->CameraStrength)) return false;
    if (!read_STI_float32(buffer, lib, &out->CameraSpecular)) return false;
    if (!read_STI_float32(buffer, lib, &out->RimStrength)) return false;
    if (!read_STI_float32(buffer, lib, &out->DirtFactor)) return false;
{
        uint16 bitfield_value = 0;
        if (!read_STI_uint16(buffer, lib, &bitfield_value)) return false;
        out->DoubleSided = (bitfield_value >> 0) & 0x1;
        out->AlphaTest = (bitfield_value >> 1) & 0x1;
        out->AlphaBlending = (bitfield_value >> 2) & 0x1;
        out->FeatureMapTint = (bitfield_value >> 3) & 0x1;
        out->WrinkleMap = (bitfield_value >> 4) & 0x1;
        out->CameraLightingEnable = (bitfield_value >> 5) & 0x1;
}
    buffer->skip(buffer, 2);
    return true;
}
