static bool read_AmmunitionTuning(Buffer* buffer, STI_TypeLibrary* lib, AmmunitionTuning* out) {
    if (!read_STI_float32(buffer, lib, &out->max_range)) return false;
    if (!read_STI_float32(buffer, lib, &out->diameter)) return false;
    if (!read_STI_float32(buffer, lib, &out->length)) return false;
    if (!read_STI_float32(buffer, lib, &out->ballistic_coefficient_front)) return false;
    if (!read_STI_float32(buffer, lib, &out->ballistic_coefficient_side)) return false;
    if (!read_STI_float32(buffer, lib, &out->drag_coefficient)) return false;
    if (!read_STI_float32(buffer, lib, &out->kinetic_energy)) return false;
    if (!read_STI_float32(buffer, lib, &out->mass)) return false;
    if (!read_STI_float32(buffer, lib, &out->projectile_damage)) return false;
    if (!read_STI_float32(buffer, lib, &out->armour_damage_multiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->organ_damage_multiplier)) return false;
    if (!read_STI_uint8(buffer, lib, &out->projectiles_per_shot)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_String(buffer, lib, &out->projectile_model_path)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_float32(buffer, lib, &out->hit_radius)) return false;
    buffer->skip(buffer, 4);
    if (!read_STI_String(buffer, lib, &out->hit_entity_spawn_tag)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_uint8(buffer, lib, &out->trigger_non_attached_entities)) return false;
    if (!read_STI_uint8(buffer, lib, &out->spawn_hit_entity_weapon_controller_only)) return false;
    if (!read_STI_uint8(buffer, lib, &out->use_arc_movement)) return false;
    if (!read_STI_uint8(buffer, lib, &out->use_staggered_arming)) return false;
    if (!read_STI_uint8(buffer, lib, &out->pierce_armor_pieces)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_String(buffer, lib, &out->projectile_entity_spawn_tag)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_float32(buffer, lib, &out->scatter_multiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->multi_projectile_scatter_angle)) return false;
    if (!read_Spline5(buffer, lib, &out->damage_falloff_curve)) return false;
    if (!read_Spline5(buffer, lib, &out->penetration_falloff_curve)) return false;
    if (!read_MissileArcSettings(buffer, lib, &out->missile_arc_settings)) return false;
    buffer->skip(buffer, 4);
    if (!read_ClusterAmmunitionSettings(buffer, lib, &out->cluster_ammunition_settings)) return false;
    return true;
}
static void free_AmmunitionTuning(AmmunitionTuning* obj, STI_TypeLibrary* lib) {
    free_Spline5(&obj->damage_falloff_curve, lib);
    free_Spline5(&obj->penetration_falloff_curve, lib);
    free_MissileArcSettings(&obj->missile_arc_settings, lib);
    free_ClusterAmmunitionSettings(&obj->cluster_ammunition_settings, lib);
}
