    fprintf(handle, "%*s%s = ", indent * 4, "", "Loadout");
    print_STI_uint8(&obj->Loadout, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "VisualVariationSeed");
    print_STI_uint32(&obj->VisualVariationSeed, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "Parts");
    fprintf(handle, "{\n%*s", (indent+1)*4, "");
    for (uint32 i = 0; i < 64; ++i) {
        print_AnimalDamageablePartSaveData(&obj->Parts[i], lib, handle, indent+1);
        if(i < 63){
            fprintf(handle,", \n%*s", (indent+1)*4, "");
        }
    }
    fprintf(handle, "\n%*s}", (indent+1)*4, "");
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "PartsCount");
    print_STI_uint8(&obj->PartsCount, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "DynamicMaterialWeights");
    fprintf(handle, "{\n%*s", (indent+1)*4, "");
    for (uint32 i = 0; i < 64; ++i) {
        print_STI_uint8(&obj->DynamicMaterialWeights[i], lib, handle, indent+1);
        if(i < 63){
            fprintf(handle,", \n%*s", (indent+1)*4, "");
        }
    }
    fprintf(handle, "\n%*s}", (indent+1)*4, "");
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "PersistentStats");
    print_MachinePersistentStatsData(&obj->PersistentStats, lib, handle, indent + 1);
