static bool read_ProceduralMissionInstance(Buffer* buffer, STI_TypeLibrary* lib, ProceduralMissionInstance* out) {
    if (!read_STI_int32(buffer, lib, &out->MissionTemplateId)) return false;
    buffer->skip(buffer, 4);
    if (!read_STI_uint64(buffer, lib, &out->HandlerId)) return false;
    if (!read_STI_int32(buffer, lib, &out->InstanceGroupId)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Location)) return false;
    if (!read_STI_uint8(buffer, lib, &out->TestOnly)) return false;
    buffer->skip(buffer, 3);
    if (!read_Vec3(buffer, lib, &out->Position)) return false;
    if (!read_STI_String(buffer, lib, &out->MapIconLabel)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_String(buffer, lib, &out->MapIconDesc)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_int32(buffer, lib, &out->ContentKey)) return false;
    if (!read_STI_int32(buffer, lib, &out->MissionDependency)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Name)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Description)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Summary)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_STI_int32(buffer, lib, &out->MissionMarkerConditions)) return false;
    return true;
}
