static bool read_RotatingPart(Buffer* buffer, STI_TypeLibrary* lib, RotatingPart* out) {
    if (!read_STI_int8(buffer, lib, &out->part_index)) return false;
    if (!read_STI_int8(buffer, lib, &out->number_of_blades)) return false;
    buffer->skip(buffer, 2);
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->position[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->rotation_axis[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->rpm_multiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->min_rpm_visible)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_rpm_visible)) return false;
    if (!read_STI_float32(buffer, lib, &out->rpm_opacity_transition)) return false;
    return true;
}
