static bool read_GenericVehicleCamera(Buffer* buffer, STI_TypeLibrary* lib, GenericVehicleCamera* out) {
    if (!read_STI_float32(buffer, lib, &out->StateTransitionTime)) return false;
    if (!read_STI_float32(buffer, lib, &out->TransitionToCrashStateDelay)) return false;
    if (!read_STI_float32(buffer, lib, &out->DriftTransitionTime)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->CameraPosition[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->CrashingCameraPosition[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->RotationPoint[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookAtPoint[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->LookAtReferenceWheelbaseRatio)) return false;
    if (!read_STI_float32(buffer, lib, &out->AddLookAtPointToPositionRatio)) return false;
    if (!read_STI_float32(buffer, lib, &out->VelDirBlendWithVehicleDirSpeed)) return false;
    if (!read_STI_float32(buffer, lib, &out->DrivingVelocityMatrixBlend)) return false;
    if (!read_STI_float32(buffer, lib, &out->MinTimeForHalfTurn)) return false;
    if (!read_STI_float32(buffer, lib, &out->YawSpringStiffness)) return false;
    if (!read_STI_float32(buffer, lib, &out->DriftYawSpringStiffness)) return false;
    if (!read_STI_float32(buffer, lib, &out->YawSpringAngleLimit)) return false;
    if (!read_STI_float32(buffer, lib, &out->YawSpringLimitStiffnessPower)) return false;
    if (!read_STI_float32(buffer, lib, &out->YawSpringStiffnessMax)) return false;
    if (!read_STI_float32(buffer, lib, &out->PitchSpringStiffness)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->PitchLimit[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->RollSpringStiffness)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->RollLimit[i])) return false;
    }
    if (!read_CameraSpring(buffer, lib, &out->LagSpring)) return false;
    if (!read_STI_float32(buffer, lib, &out->LagCameraRelativity)) return false;
    if (!read_STI_float32(buffer, lib, &out->LagVelocityScale)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->FollowCameraRange[i])) return false;
    }
    if (!read_CameraSpring(buffer, lib, &out->CameraVelocitySpring)) return false;
    if (!read_CameraSpring(buffer, lib, &out->LookAtVelocitySpring)) return false;
    if (!read_STI_float32(buffer, lib, &out->UpCameraVelocityRefSpeedKph)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->UpCameraRange[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->UpLookAtVelocityRefSpeedKph)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->UpLookAtRange[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->RightCameraVelocityRefSpeedKph)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->RightCameraRange[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->RightLookAtVelocityRefSpeedKph)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->RightLookAtRange[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->RollWithVehicleAmount)) return false;
    if (!read_STI_float32(buffer, lib, &out->ReCenterDelay)) return false;
    if (!read_STI_float32(buffer, lib, &out->ReCenterSpeed)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->FOVVelocityRange[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->FOV[i])) return false;
    }
    if (!read_CameraSpring(buffer, lib, &out->FOVBlendSpring)) return false;
    if (!read_STI_float32(buffer, lib, &out->FOVZoomAdjustment)) return false;
    if (!read_CameraSpring(buffer, lib, &out->CollisionBlendSpring)) return false;
    if (!read_STI_float32(buffer, lib, &out->CollisionFudgeFactor)) return false;
    if (!read_STI_uint8(buffer, lib, &out->CollisionPitchEnabled)) return false;
    buffer->skip(buffer, 3);
    if (!read_CameraSpring(buffer, lib, &out->CollisionPitchSpring)) return false;
    if (!read_STI_float32(buffer, lib, &out->CollisionPitchDistance)) return false;
    if (!read_STI_uint32(buffer, lib, &out->CollisionCheckWater)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->CollisionStartPoint[i])) return false;
    }
    if (!read_CameraTowing(buffer, lib, &out->TowingOffsets)) return false;
    if (!read_STI_uint8(buffer, lib, &out->AlignReferenceWithWorldUp)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_uint32(buffer, lib, &out->DrawDebugInfo)) return false;
    if (!read_STI_float32(buffer, lib, &out->ListenerHeadRelativity)) return false;
    if (!read_InputStick(buffer, lib, &out->InputSettings)) return false;
    if (!read_VehicleSplineFuncOfPitchParams(buffer, lib, &out->SplineFuncOfPitchParams)) return false;
    return true;
}
static void free_GenericVehicleCamera(GenericVehicleCamera* obj, STI_TypeLibrary* lib) {
    free_CameraSpring(&obj->LagSpring, lib);
    free_CameraSpring(&obj->CameraVelocitySpring, lib);
    free_CameraSpring(&obj->LookAtVelocitySpring, lib);
    free_CameraSpring(&obj->FOVBlendSpring, lib);
    free_CameraSpring(&obj->CollisionBlendSpring, lib);
    free_CameraSpring(&obj->CollisionPitchSpring, lib);
    free_CameraTowing(&obj->TowingOffsets, lib);
    free_InputStick(&obj->InputSettings, lib);
    free_VehicleSplineFuncOfPitchParams(&obj->SplineFuncOfPitchParams, lib);
}
