static bool read_Spline5(Buffer* buffer, STI_TypeLibrary* lib, Spline5* out) {
    if (!read_STI_float32(buffer, lib, &out->x_min)) return false;
    if (!read_STI_float32(buffer, lib, &out->x_max)) return false;
    if (!read_STI_float32(buffer, lib, &out->y_min)) return false;
    if (!read_STI_float32(buffer, lib, &out->y_max)) return false;
    if (!read_STI_int8(buffer, lib, &out->interpolation_type)) return false;
    if (!read_STI_int8(buffer, lib, &out->number_of_control_points)) return false;
    buffer->skip(buffer, 2);
    for (uint32 i = 0; i < 5; ++i) {
        if (!read_SplineControlPoint(buffer, lib, &out->control_points[i])) return false;
    }
    return true;
}
static void free_Spline5(Spline5* obj, STI_TypeLibrary* lib) {
    for (uint32 i = 0; i < 5; ++i) {
        free_SplineControlPoint(&obj->control_points[i], lib);
    }
}
