static bool read_AmfMesh(Buffer* buffer, STI_TypeLibrary* lib, AmfMesh* out) {
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->MeshTypeId)) return false;
    if (!read_STI_uint32(buffer, lib, &out->IndexCount)) return false;
    if (!read_STI_uint32(buffer, lib, &out->VertexCount)) return false;
    if (!read_STI_uint8(buffer, lib, &out->IndexBufferIndex)) return false;
    if (!read_STI_uint8(buffer, lib, &out->IndexBufferStride)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_uint32(buffer, lib, &out->IndexBufferOffset)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_STI_uint8(buffer, lib, &out->VertexBufferIndices)) return false;
    if (!read_DynamicArray_STI_uint8(buffer, lib, &out->VertexStreamStrides)) return false;
    if (!read_DynamicArray_STI_uint32(buffer, lib, &out->VertexStreamOffsets)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->TextureDensities[i])) return false;
    }
    buffer->skip(buffer, 4);
    if (!read_STI_Deferred(buffer, lib, &out->MeshProperties)) return false;
    if (!read_DynamicArray_STI_int16(buffer, lib, &out->BoneIndexLookup)) return false;
    if (!read_DynamicArray_AmfSubMesh(buffer, lib, &out->SubMeshes)) return false;
    if (!read_DynamicArray_AmfStreamAttribute(buffer, lib, &out->StreamAttributes)) return false;
    return true;
}
static void free_AmfMesh(AmfMesh* obj, STI_TypeLibrary* lib) {
    free_DynamicArray_STI_uint8(&obj->VertexBufferIndices, lib);
    free_DynamicArray_STI_uint8(&obj->VertexStreamStrides, lib);
    free_DynamicArray_STI_uint32(&obj->VertexStreamOffsets, lib);
    free_STI_Deferred(&obj->MeshProperties, lib);
    free_DynamicArray_STI_int16(&obj->BoneIndexLookup, lib);
    free_DynamicArray_AmfSubMesh(&obj->SubMeshes, lib);
    free_DynamicArray_AmfStreamAttribute(&obj->StreamAttributes, lib);
}
