static bool read_TerrainOccluderMesh(Buffer* buffer, STI_TypeLibrary* lib, TerrainOccluderMesh* out) {
    for (uint32 i = 0; i < 6; ++i) {
        if (!read_STI_float32(buffer, lib, &out->BoundingBox[i])) return false;
    }
    if (!read_DynamicArray_STI_uint16(buffer, lib, &out->Vertices)) return false;
    if (!read_DynamicArray_STI_uint16(buffer, lib, &out->Indices)) return false;
{
        uint32 bitfield_value = 0;
        if (!read_STI_uint32(buffer, lib, &bitfield_value)) return false;
        out->TriangleOmitted = (bitfield_value >> 0) & 0x1;
}
    buffer->skip(buffer, 4);
    return true;
}
