    if (!read_Vec3(buffer, lib, &out->Position)) return false;
    if (!read_STI_uint32(buffer, lib, &out->ReserveId)) return false;
    if (!read_STI_uint32(buffer, lib, &out->ToolTipId)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_STI_uint64(buffer, lib, &out->GlobalShowEvent)) return false;
    if (!read_DynamicArray_STI_uint64(buffer, lib, &out->GlobalHideEvent)) return false;
    if (!read_STI_String(buffer, lib, &out->LabelKey)) return false;
    buffer->skip(buffer, -8);
