static bool read_DynamicArray_EntityDisplayStat(Buffer* buffer, STI_TypeLibrary* lib, DynamicArray_EntityDisplayStat* out) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!read_STI_uint32(buffer, lib, &offset)) return false;
    if (!read_STI_uint32(buffer, lib, &unk0)) return false;
    if (!read_STI_uint32(buffer, lib, &count)) return false;
    if (!read_STI_uint32(buffer, lib, &unk1)) return false;
    DA_init(out, EntityDisplayStat, count);
    if (count>0) {
        int64 original_offset = 0;
        if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
        if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
        for (uint32 i = 0; i < count; ++i) {
            if (!read_EntityDisplayStat(buffer, lib, &out->items[i])) return false;
        }
        out->count = count;
        if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}
static void free_DynamicArray_EntityDisplayStat(DynamicArray_EntityDisplayStat* obj, STI_TypeLibrary* lib) {
    for (uint32 i = 0; i < obj->count; ++i) {
        free_EntityDisplayStat(&obj->items[i], lib);
    }
    DA_free(obj);
}
static void print_DynamicArray_EntityDisplayStat(const DynamicArray_EntityDisplayStat* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "DynamicArray_EntityDisplayStat {\n");
    indent++;
    if (obj->count>50) {
        fprintf(handle, "%*s", indent * 4, "");
        print_EntityDisplayStat(&obj->items[0], lib, handle, indent + 1);
        fprintf(handle, "\n%*s...\n%*s", indent * 4, "", indent * 4, "");
        print_EntityDisplayStat(&obj->items[obj->count-1], lib, handle, indent+1);
        fprintf(handle, "\n");
    } else {
        fprintf(handle, "%*s", indent*4, "");
        for (uint32 i = 0; i < obj->count; ++i) {
            print_EntityDisplayStat(&obj->items[i], lib, handle, indent+1);
            if(i < obj->count-1){
                fprintf(handle,", \n%*s", indent*4, "");
            }
        }
        fprintf(handle, "\n");
    }
    fprintf(handle, "%*s}", (indent - 1) * 4, "");
}
static bool read_CharacterProfile2(Buffer* buffer, STI_TypeLibrary* lib, CharacterProfile2* out) {
    if (!read_CharacterLooks(buffer, lib, &out->CharacterLooks)) return false;
    for (uint32 i = 0; i < 128; ++i) {
        if (!read_STI_uint32(buffer, lib, &out->Skills[i])) return false;
    }
    for (uint32 i = 0; i < 128; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->SkillLevel[i])) return false;
    }
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_uint32(buffer, lib, &out->SkillPointsSpent[i])) return false;
    }
    if (!read_STI_uint32(buffer, lib, &out->SkillPoints)) return false;
    if (!read_STI_uint32(buffer, lib, &out->ActiveSkill)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Xp)) return false;
    if (!read_STI_uint16(buffer, lib, &out->Level)) return false;
    if (!read_STI_uint8(buffer, lib, &out->Created)) return false;
    buffer->skip(buffer, 1);
    if (!read_DynamicArray_OwnedEquipment1(buffer, lib, &out->Inventory)) return false;
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_uint32(buffer, lib, &out->PPInventorySlot[i])) return false;
    }
    if (!read_DynamicArray_VehicleData(buffer, lib, &out->VehicleData)) return false;
    if (!read_STI_uint8(buffer, lib, &out->VehiclePreferedCameraThirdPerson)) return false;
    if (!read_STI_uint8(buffer, lib, &out->BackpackSizeColumns)) return false;
    if (!read_STI_uint8(buffer, lib, &out->BackpackSizeRows)) return false;
    buffer->skip(buffer, 5);
    if (!read_DynamicArray_STI_uint32(buffer, lib, &out->EmotesUnlocked)) return false;
    for (uint32 i = 0; i < 8; ++i) {
        if (!read_STI_uint32(buffer, lib, &out->EmoteSlots[i])) return false;
    }
    if (!read_DynamicArray_STI_uint64(buffer, lib, &out->Collectables)) return false;
    if (!read_STI_float32(buffer, lib, &out->DistanceTravelled)) return false;
    if (!read_STI_float32(buffer, lib, &out->TimeOfDay)) return false;
    if (!read_STI_float32(buffer, lib, &out->WeatherTime)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_PlayerPosition(buffer, lib, &out->PlayerPositions)) return false;
    if (!read_STI_uint64(buffer, lib, &out->LastLevelUpTS)) return false;
    if (!read_DynamicArray_STI_uint32(buffer, lib, &out->GivenDLCItems)) return false;
    if (!read_DynamicArray_RaidLootSaveData(buffer, lib, &out->RaidLootAcquired)) return false;
    return true;
}
static void free_CharacterProfile2(CharacterProfile2* obj, STI_TypeLibrary* lib) {
    free_CharacterLooks(&obj->CharacterLooks, lib);
    free_DynamicArray_OwnedEquipment1(&obj->Inventory, lib);
    free_DynamicArray_VehicleData(&obj->VehicleData, lib);
    free_DynamicArray_STI_uint32(&obj->EmotesUnlocked, lib);
    free_DynamicArray_STI_uint64(&obj->Collectables, lib);
    free_DynamicArray_PlayerPosition(&obj->PlayerPositions, lib);
    free_DynamicArray_STI_uint32(&obj->GivenDLCItems, lib);
    free_DynamicArray_RaidLootSaveData(&obj->RaidLootAcquired, lib);
}
