static bool read_LandEngine(Buffer* buffer, STI_TypeLibrary* lib, LandEngine* out) {
    if (!read_STI_int32(buffer, lib, &out->rpm_power_band)) return false;
    if (!read_STI_float32(buffer, lib, &out->resistance_at_min_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->resistance_at_max_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->resistance_at_optimal_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->rev_limiter_rpm_drop)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->min_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->optimal_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->torque_factor_at_max_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->torque_factor_at_min_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->torque_factor_at_optimal_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->clutch_slip_rpm)) return false;
    if (!read_STI_float32(buffer, lib, &out->engine_min_noise)) return false;
    if (!read_STI_float32(buffer, lib, &out->engine_damage_noise_scale)) return false;
    if (!read_STI_float32(buffer, lib, &out->engine_max_damage_torque)) return false;
    return true;
}
