static bool read_FollowSpringModifierParams(Buffer* buffer, STI_TypeLibrary* lib, FollowSpringModifierParams* out) {
    if (!read_STI_uint8(buffer, lib, &out->BypassModifier)) return false;
    if (!read_STI_uint8(buffer, lib, &out->XZOnly)) return false;
    buffer->skip(buffer, 2);
    if (!read_CameraSpring(buffer, lib, &out->FollowSpring)) return false;
    if (!read_STI_float32(buffer, lib, &out->FollowCameraRelativity)) return false;
    if (!read_STI_uint8(buffer, lib, &out->UseStuckBehavior)) return false;
    buffer->skip(buffer, 3);
    if (!read_CameraSpring(buffer, lib, &out->StuckSpring)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxSpeedWhenStuck)) return false;
    if (!read_STI_float32(buffer, lib, &out->DistWhenStuck)) return false;
    if (!read_CameraSpline5(buffer, lib, &out->SpeedToDistSpline)) return false;
    if (!read_CameraSpline5(buffer, lib, &out->PitchScaleSpline)) return false;
    if (!read_STI_uint8(buffer, lib, &out->DrawDebug)) return false;
    buffer->skip(buffer, 3);
    return true;
}
static void free_FollowSpringModifierParams(FollowSpringModifierParams* obj, STI_TypeLibrary* lib) {
    free_CameraSpring(&obj->FollowSpring, lib);
    free_CameraSpring(&obj->StuckSpring, lib);
    free_CameraSpline5(&obj->SpeedToDistSpline, lib);
    free_CameraSpline5(&obj->PitchScaleSpline, lib);
}
