static bool read_GeneralConstants(Buffer* buffer, STI_TypeLibrary* lib, GeneralConstants* out) {
    if (!read_STI_float32(buffer, lib, &out->DepthBias)) return false;
    if (!read_STI_float32(buffer, lib, &out->SpecularPower)) return false;
{
        uint16 bitfield_value = 0;
        if (!read_STI_uint16(buffer, lib, &bitfield_value)) return false;
        out->DoubleSided = (bitfield_value >> 0) & 0x1;
        out->AlphaBlending = (bitfield_value >> 1) & 0x1;
        out->AdditiveBlending = (bitfield_value >> 2) & 0x1;
        out->AnimateTexture = (bitfield_value >> 3) & 0x1;
        out->AlphaTest = (bitfield_value >> 4) & 0x1;
        out->DiffuseChannel = (bitfield_value >> 5) & 0x7;
        out->AOChannel = (bitfield_value >> 8) & 0x7;
}
    buffer->skip(buffer, 2);
    return true;
}
static void free_GeneralConstants(GeneralConstants* obj, STI_TypeLibrary* lib) {
}
