    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "SpecularPower");
    print_STI_float32(&obj->SpecularPower, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "DoubleSided");
    fprintf(handle, "%i", obj->DoubleSided);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "AlphaBlending");
    fprintf(handle, "%i", obj->AlphaBlending);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "AdditiveBlending");
    fprintf(handle, "%i", obj->AdditiveBlending);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "AnimateTexture");
