static bool read_AnimalPopulationSaveData(Buffer* buffer, STI_TypeLibrary* lib, AnimalPopulationSaveData* out) {
    if (!read_STI_uint32(buffer, lib, &out->NameHashId)) return false;
    for (uint32 i = 0; i < 64; ++i) {
        if (!read_AnimalRepopulateSaveData(buffer, lib, &out->RepopulateData[i])) return false;
    }
    if (!read_STI_uint32(buffer, lib, &out->RepopulateCount)) return false;
    return true;
}
static void free_AnimalPopulationSaveData(AnimalPopulationSaveData* obj, STI_TypeLibrary* lib) {
    for (uint32 i = 0; i < 64; ++i) {
        free_AnimalRepopulateSaveData(&obj->RepopulateData[i], lib);
    }
}
static void print_AnimalPopulationSaveData(const AnimalPopulationSaveData* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "AnimalPopulationSaveData {\n");
    indent++;
    fprintf(handle, "%*s%s = ", indent * 4, "", "NameHashId");
    print_STI_uint32(&obj->NameHashId, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "RepopulateData");
    fprintf(handle, "{\n%*s", (indent+1)*4, "");
    for (uint32 i = 0; i < 64; ++i) {
        print_AnimalRepopulateSaveData(&obj->RepopulateData[i], lib, handle, indent+1);
        if(i < 63){
            fprintf(handle,", \n%*s", (indent+1)*4, "");
        }
    }
    fprintf(handle, "\n%*s}", (indent+1)*4, "");
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "RepopulateCount");
    print_STI_uint32(&obj->RepopulateCount, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s}", (indent - 1)*4, "");
}
