static bool read_CarPaintMMConstants(Buffer* buffer, STI_TypeLibrary* lib, CarPaintMMConstants* out) {
    if (!read_CarPaintMMStaticConstants(buffer, lib, &out->Static)) return false;
    if (!read_CarPaintMMDynamicConstants(buffer, lib, &out->Dynamic)) return false;
    if (!read_STI_float32(buffer, lib, &out->GIEmissionModulator)) return false;
{
        uint16 bitfield_value = 0;
        if (!read_STI_uint16(buffer, lib, &bitfield_value)) return false;
        out->Decals = (bitfield_value >> 0) & 0x1;
        out->UseDamageBlend = (bitfield_value >> 1) & 0x1;
        out->Dirt = (bitfield_value >> 2) & 0x1;
        out->Tint = (bitfield_value >> 3) & 0x1;
        out->TintSoftBlend = (bitfield_value >> 4) & 0x1;
        out->Layered = (bitfield_value >> 5) & 0x1;
        out->Overlay = (bitfield_value >> 6) & 0x1;
        out->TwoSided = (bitfield_value >> 7) & 0x1;
        out->AlphaBlend = (bitfield_value >> 8) & 0x1;
        out->AlphaTest = (bitfield_value >> 9) & 0x1;
        out->Rotating = (bitfield_value >> 10) & 0x1;
}
    buffer->skip(buffer, 2);
    return true;
}
static void free_CarPaintMMConstants(CarPaintMMConstants* obj, STI_TypeLibrary* lib) {
    free_CarPaintMMStaticConstants(&obj->Static, lib);
    free_CarPaintMMDynamicConstants(&obj->Dynamic, lib);
}
