static bool read_WindowConstants(Buffer* buffer, STI_TypeLibrary* lib, WindowConstants* out) {
    if (!read_STI_float32(buffer, lib, &out->SpecGloss)) return false;
    if (!read_STI_float32(buffer, lib, &out->SpecFresnel)) return false;
    if (!read_STI_float32(buffer, lib, &out->DiffuseRoughness)) return false;
    if (!read_STI_float32(buffer, lib, &out->TintPower)) return false;
    if (!read_STI_float32(buffer, lib, &out->TintMultiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->MinAlpha)) return false;
    if (!read_STI_float32(buffer, lib, &out->UVScale)) return false;
    if (!read_STI_float32(buffer, lib, &out->ChromaticAberration)) return false;
    if (!read_STI_float32(buffer, lib, &out->RefractionStrength)) return false;
{
        uint8 bitfield_value = 0;
        if (!read_STI_uint8(buffer, lib, &bitfield_value)) return false;
        out->Simple = (bitfield_value >> 0) & 0x1;
        out->OneSided = (bitfield_value >> 1) & 0x1;
        out->LensOcclusion = (bitfield_value >> 2) & 0x1;
}
    buffer->skip(buffer, 3);
    return true;
}
