    if (!read_TrainCommon(buffer, lib, &out->train_common)) return false;
    if (!read_TireEffectsCommon(buffer, lib, &out->tire_effects)) return false;
    buffer->skip(buffer, 4);
    if (!read_VehicleDamageCommon(buffer, lib, &out->vehicle_damage)) return false;
    if (!read_RotorCollision(buffer, lib, &out->rotor_collision)) return false;
    if (!read_DynamicArray_DoorPartProperties(buffer, lib, &out->all_door_part_properties)) return false;
    if (!read_DynamicArray_FinPartProperties(buffer, lib, &out->all_fin_part_properties)) return false;
