    if (!read_STI_float32(buffer, lib, &out->deceleration_freespin_multiply)) return false;
    if (!read_STI_float32(buffer, lib, &out->thrust_smoothing)) return false;
    if (!read_STI_float32(buffer, lib, &out->freespin_control)) return false;
    buffer->skip(buffer, 4);
