static bool read_CachedFile(Buffer* buffer, STI_TypeLibrary* lib, CachedFile* out) {
    for (uint32 i = 0; i < 64; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->Hash[i])) return false;
    }
    if (!read_STI_uint64(buffer, lib, &out->Expiry)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Url_Hash)) return false;
    buffer->skip(buffer, 4);
    return true;
}
static void free_CachedFile(CachedFile* obj, STI_TypeLibrary* lib) {
}
static void print_CachedFile(const CachedFile* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "CachedFile {\n");
    indent++;
    fprintf(handle, "%*s%s = ", indent * 4, "", "Hash");
    fprintf(handle, "{\n%*s", (indent+1)*4, "");
    for (uint32 i = 0; i < 64; ++i) {
        print_STI_uint8(&obj->Hash[i], lib, handle, indent+1);
        if(i < 63){
            fprintf(handle,", \n%*s", (indent+1)*4, "");
        }
    }
    fprintf(handle, "\n%*s}", (indent+1)*4, "");
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "Expiry");
    print_STI_uint64(&obj->Expiry, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "Url_Hash");
    print_STI_uint32(&obj->Url_Hash, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s}", (indent - 1)*4, "");
}
