static bool read_Fins(Buffer* buffer, STI_TypeLibrary* lib, Fins* out) {
    if (!read_Spline5(buffer, lib, &out->lift_vs_attack_angle_deg)) return false;
    if (!read_Spline5(buffer, lib, &out->max_steering_vs_speed_ms)) return false;
    if (!read_STI_float32(buffer, lib, &out->reference_speed_ms)) return false;
    if (!read_STI_float32(buffer, lib, &out->pressure_drag)) return false;
    if (!read_STI_float32(buffer, lib, &out->pressure_drag2)) return false;
    buffer->skip(buffer, 4);
    for (uint32 i = 0; i < 5; ++i) {
        if (!read_Fin(buffer, lib, &out->fins[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->number_of_fins)) return false;
    buffer->skip(buffer, 7);
    return true;
}
static void free_Fins(Fins* obj, STI_TypeLibrary* lib) {
    free_Spline5(&obj->lift_vs_attack_angle_deg, lib);
    free_Spline5(&obj->max_steering_vs_speed_ms, lib);
    for (uint32 i = 0; i < 5; ++i) {
        free_Fin(&obj->fins[i], lib);
    }
}
static void print_Fins(const Fins* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "Fins {\n");
    indent++;
    fprintf(handle, "%*s%s = ", indent * 4, "", "lift_vs_attack_angle_deg");
    print_Spline5(&obj->lift_vs_attack_angle_deg, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "max_steering_vs_speed_ms");
    print_Spline5(&obj->max_steering_vs_speed_ms, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "reference_speed_ms");
    print_STI_float32(&obj->reference_speed_ms, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "pressure_drag");
    print_STI_float32(&obj->pressure_drag, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "pressure_drag2");
    print_STI_float32(&obj->pressure_drag2, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "fins");
    fprintf(handle, "{\n%*s", (indent+1)*4, "");
    for (uint32 i = 0; i < 5; ++i) {
        print_Fin(&obj->fins[i], lib, handle, indent+1);
        if(i < 4){
            fprintf(handle,", \n%*s", (indent+1)*4, "");
        }
    }
    fprintf(handle, "\n%*s}", (indent+1)*4, "");
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "number_of_fins");
    print_STI_uint8(&obj->number_of_fins, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s}", (indent - 1)*4, "");
}
