    if (!read_DynamicArray_OwnedEquipment1(buffer, lib, &out->UnknownItemsStash)) return false;
    if (!read_DynamicArray_OwnedEquipment1(buffer, lib, &out->InaccessibleItems)) return false;
    if (!read_DynamicArray_STI_uint32(buffer, lib, &out->GivenDLCItems)) return false;
    if (!read_STI_uint32(buffer, lib, &out->ActiveCharacterIndex)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_MissionSaveData2(buffer, lib, &out->MissionCampaigns)) return false;
    if (!read_DynamicArray_STI_int32(buffer, lib, &out->MissionCampaignsReserveIds)) return false;
    return true;
