static bool read_RoadInfoEx(Buffer* buffer, STI_TypeLibrary* lib, RoadInfoEx* out) {
    if (!read_DynamicArray_STI_float32(buffer, lib, &out->SplinePoints)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->AABBMin[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->AABBMax[i])) return false;
    }
    if (!read_STI_uint64(buffer, lib, &out->GameObjectID)) return false;
    if (!read_STI_float32(buffer, lib, &out->Length)) return false;
    if (!read_STI_uint8(buffer, lib, &out->LaneCount)) return false;
    if (!read_STI_uint8(buffer, lib, &out->TraverseType)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_float32(buffer, lib, &out->LaneWidth)) return false;
    if (!read_STI_uint16(buffer, lib, &out->DistBetweenVehicles)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_float32(buffer, lib, &out->SpeedLimit)) return false;
    buffer->skip(buffer, 4);
    return true;
}
