static bool read_Propeller(Buffer* buffer, STI_TypeLibrary* lib, Propeller* out) {
    if (!read_HashString(buffer, lib, &out->physics_component_name)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->hinge_position[i])) return false;
    }
    if (!read_EulerAngles(buffer, lib, &out->hinge_angles)) return false;
    if (!read_STI_float32(buffer, lib, &out->trim_flattening_in_turns)) return false;
    if (!read_STI_float32(buffer, lib, &out->distance_to_hinge)) return false;
    if (!read_STI_float32(buffer, lib, &out->min_angle_deg)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_angle_deg)) return false;
    if (!read_DockingPropLimits(buffer, lib, &out->docking_limits)) return false;
    if (!read_STI_float32(buffer, lib, &out->zero_angle_deg)) return false;
    if (!read_STI_uint8(buffer, lib, &out->is_impeller)) return false;
    buffer->skip(buffer, 3);
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->impeller_intake_position[i])) return false;
    }
    buffer->skip(buffer, 4);
    return true;
}
static void free_Propeller(Propeller* obj, STI_TypeLibrary* lib) {
    free_HashString(&obj->physics_component_name, lib);
    free_EulerAngles(&obj->hinge_angles, lib);
    free_DockingPropLimits(&obj->docking_limits, lib);
}
