static bool read_FirstPersonCameraModifierParams_2(Buffer* buffer, STI_TypeLibrary* lib, FirstPersonCameraModifierParams_2* out) {
    if (!read_STI_uint8(buffer, lib, &out->DrawDebug)) return false;
    if (!read_STI_uint8(buffer, lib, &out->BypassModifier)) return false;
    buffer->skip(buffer, 2);
    if (!read_CameraInputParams_2(buffer, lib, &out->InputParams)) return false;
    if (!read_STI_float32(buffer, lib, &out->ForegroundFOV)) return false;
    if (!read_STI_float32(buffer, lib, &out->WorldFOV)) return false;
    if (!read_STI_uint8(buffer, lib, &out->UseGameSettingsWorldFov)) return false;
    buffer->skip(buffer, 7);
    if (!read_STI_String(buffer, lib, &out->ForegroundBBKey)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_uint8(buffer, lib, &out->ForegroundPitchEnabled)) return false;
    buffer->skip(buffer, 7);
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_String(buffer, lib, &out->AimAdjustmentSegments[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->AlignToSurface)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_float32(buffer, lib, &out->AlignToSurfaceStiffness)) return false;
    if (!read_STI_float32(buffer, lib, &out->ProneAllowedHeightPushUp)) return false;
    if (!read_STI_float32(buffer, lib, &out->PronePushUpRayLength)) return false;
    if (!read_STI_float32(buffer, lib, &out->PronePushUpRayBackOffset)) return false;
    if (!read_AimAssistParams(buffer, lib, &out->AimAssist)) return false;
    buffer->skip(buffer, 4);
    return true;
}
static void free_FirstPersonCameraModifierParams_2(FirstPersonCameraModifierParams_2* obj, STI_TypeLibrary* lib) {
    free_CameraInputParams_2(&obj->InputParams, lib);
    free_AimAssistParams(&obj->AimAssist, lib);
}
