static bool read_Part(Buffer* buffer, STI_TypeLibrary* lib, Part* out) {
    if (!read_HashString(buffer, lib, &out->name)) return false;
    if (!read_HashString(buffer, lib, &out->damage_type)) return false;
    if (!read_HashString(buffer, lib, &out->behavior)) return false;
    if (!read_HashString(buffer, lib, &out->model)) return false;
    if (!read_HashString(buffer, lib, &out->model_swap)) return false;
    if (!read_STI_int8(buffer, lib, &out->part_index)) return false;
    if (!read_STI_int8(buffer, lib, &out->parent_part_index)) return false;
    buffer->skip(buffer, 2);
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_float32(buffer, lib, &out->parent_space_offset[i])) return false;
    }
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_float32(buffer, lib, &out->bind_pose_bone_matrix[i])) return false;
    }
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_STI_int8(buffer, lib, &out->children_part_indices)) return false;
    if (!read_STI_int8(buffer, lib, &out->starts_loose)) return false;
    if (!read_STI_int8(buffer, lib, &out->should_break)) return false;
    if (!read_STI_int8(buffer, lib, &out->prevent_mesh_swap_while_alive)) return false;
    if (!read_STI_int8(buffer, lib, &out->prevent_loosening_while_alive)) return false;
    if (!read_STI_int8(buffer, lib, &out->prevent_breaking_while_alive)) return false;
    if (!read_STI_int8(buffer, lib, &out->always_mesh_swap_on_death)) return false;
    if (!read_STI_int8(buffer, lib, &out->always_loosen_on_death)) return false;
    if (!read_STI_int8(buffer, lib, &out->always_break_on_death)) return false;
    if (!read_STI_int8(buffer, lib, &out->disappears_when_broken)) return false;
    if (!read_STI_int8(buffer, lib, &out->appears_on_death)) return false;
    if (!read_STI_int8(buffer, lib, &out->disappears_on_death)) return false;
    if (!read_STI_int8(buffer, lib, &out->starts_deleted)) return false;
    if (!read_STI_int8(buffer, lib, &out->is_deformable)) return false;
    if (!read_STI_int8(buffer, lib, &out->has_lights)) return false;
    if (!read_STI_int8(buffer, lib, &out->has_world_collision_shape)) return false;
    if (!read_STI_int8(buffer, lib, &out->only_collides_once_loose)) return false;
    if (!read_STI_int8(buffer, lib, &out->only_collides_once_broken)) return false;
    buffer->skip(buffer, 7);
    if (!read_DynamicArray_STI_int16(buffer, lib, &out->hide_parts_when_broken)) return false;
    if (!read_DynamicArray_STI_int16(buffer, lib, &out->meshswap_parts_when_broken)) return false;
    if (!read_DynamicArray_STI_int16(buffer, lib, &out->loosen_parts_when_broken)) return false;
    if (!read_DynamicArray_STI_int16(buffer, lib, &out->break_parts_when_broken)) return false;
    if (!read_STI_int16(buffer, lib, &out->world_collision_instance_id)) return false;
    if (!read_STI_int16(buffer, lib, &out->raycast_instance_id)) return false;
    if (!read_STI_int16(buffer, lib, &out->grandpa_world_instance_id)) return false;
    if (!read_STI_int16(buffer, lib, &out->grandpa_raycast_instance_id)) return false;
    if (!read_STI_int16(buffer, lib, &out->world_collision_body_id)) return false;
    if (!read_STI_int16(buffer, lib, &out->raycast_body_id)) return false;
    if (!read_STI_int16(buffer, lib, &out->constraint_index)) return false;
    buffer->skip(buffer, 2);
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->centroid[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->deformation_centroid_offset[i])) return false;
    }
    return true;
}
