static bool read_RivalData(Buffer* buffer, STI_TypeLibrary* lib, RivalData* out) {
    if (!read_STI_uint32(buffer, lib, &out->MaxRivals)) return false;
    if (!read_STI_uint32(buffer, lib, &out->PlayerKillXP)) return false;
    if (!read_STI_float32(buffer, lib, &out->RivalCreationCooldown)) return false;
    if (!read_STI_float32(buffer, lib, &out->RivalMissionCooldown)) return false;
    if (!read_STI_float32(buffer, lib, &out->MachineKillMultiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->RivalKillMultiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->RivalXPMultiplier)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_RegionTitle(buffer, lib, &out->HostKillTitles)) return false;
    if (!read_DynamicArray_RegionTitle(buffer, lib, &out->ClientKillTitles)) return false;
    if (!read_DynamicArray_RegionTitleCollection(buffer, lib, &out->RegionTitles)) return false;
    if (!read_DynamicArray_RivalLevel(buffer, lib, &out->RivalLevels)) return false;
    if (!read_DynamicArray_ControlPointLevel(buffer, lib, &out->ControlPointLevels)) return false;
    if (!read_DynamicArray_InsurrectionLevel(buffer, lib, &out->InsurrectionLevels)) return false;
    if (!read_DynamicArray_RivalNames(buffer, lib, &out->RivalNames)) return false;
    if (!read_DynamicArray_RivalMissionGroupData(buffer, lib, &out->RivalMissionGroups)) return false;
    if (!read_DynamicArray_RivalMissionComplete(buffer, lib, &out->RivalMissionCompletes)) return false;
    if (!read_RivalTerminalData(buffer, lib, &out->RivalTerminalData)) return false;
    return true;
}
