    if (!read_STI_float32(buffer, lib, &out->fire_spreading_speed_ms)) return false;
    if (!read_STI_float32(buffer, lib, &out->min_water_entry_ms)) return false;
    if (!read_STI_float32(buffer, lib, &out->fatal_water_entry_ms)) return false;
