static bool read_ProceduralShakeParams(Buffer* buffer, STI_TypeLibrary* lib, ProceduralShakeParams* out) {
    if (!read_STI_uint8(buffer, lib, &out->BypassModifier)) return false;
    if (!read_STI_uint8(buffer, lib, &out->SyncPhase)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_float32(buffer, lib, &out->PitchFrequency)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->PitchAmplitude[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->RollFrequency)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->RollAmplitude[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->YawFrequency)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->YawAmplitude[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->LocalXFrequency)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LocalXAmplitude[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->LocalYFrequency)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LocalYAmplitude[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->LocalZFrequency)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LocalZAmplitude[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->SpeedRange[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SpeedMaxScale)) return false;
    return true;
}
