static bool read_AdfModelCollectionInstance(Buffer* buffer, STI_TypeLibrary* lib, AdfModelCollectionInstance* out) {
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Transform[i])) return false;
    }
    if (!read_STI_uint16(buffer, lib, &out->ModelIndex)) return false;
{
        uint16 bitfield_value = 0;
        if (!read_STI_uint16(buffer, lib, &bitfield_value)) return false;
        out->CastShadow = (bitfield_value >> 0) & 0x1;
        out->ClipOnDistance = (bitfield_value >> 1) & 0x1;
        out->SizeCull = (bitfield_value >> 2) & 0x1;
        out->SandAmount = (bitfield_value >> 3) & 0x1FFF;
}
    for (uint32 i = 0; i < 6; ++i) {
        if (!read_STI_float32(buffer, lib, &out->AABB[i])) return false;
    }
    return true;
}
