    fprintf(handle, "%*s%s = ", indent * 4, "", "ModelIndex");
    print_STI_uint16(&obj->ModelIndex, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "CastShadow");
    fprintf(handle, "%i", obj->CastShadow);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "ClipOnDistance");
