static bool read_VehicleDamage(Buffer* buffer, STI_TypeLibrary* lib, VehicleDamage* out) {
    if (!read_STI_int32(buffer, lib, &out->max_health)) return false;
    if (!read_STI_int32(buffer, lib, &out->bullet_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->bullet_armor_strength)) return false;
    if (!read_STI_int32(buffer, lib, &out->bullet_heavy_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->bullet_heavy_armor_strength)) return false;
    if (!read_STI_int32(buffer, lib, &out->explosion_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->explosion_armor_strength)) return false;
    if (!read_STI_int32(buffer, lib, &out->impact_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->impact_armor_strength)) return false;
    if (!read_STI_int32(buffer, lib, &out->fire_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->fire_armor_strength)) return false;
    if (!read_STI_int32(buffer, lib, &out->melee_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->melee_armor_strength)) return false;
    if (!read_STI_int32(buffer, lib, &out->electricity_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->electricity_armor_strength)) return false;
    if (!read_STI_int32(buffer, lib, &out->grapple_pull_armor)) return false;
    if (!read_STI_float32(buffer, lib, &out->grapple_pull_armor_strength)) return false;
    if (!read_STI_float32(buffer, lib, &out->impact_damage_factor)) return false;
    if (!read_STI_float32(buffer, lib, &out->deform_scale)) return false;
    if (!read_STI_uint16(buffer, lib, &out->smoke_threshold)) return false;
    if (!read_STI_uint16(buffer, lib, &out->heavy_smoke_threshold)) return false;
    if (!read_STI_int8(buffer, lib, &out->burn_enabled)) return false;
    buffer->skip(buffer, 1);
    if (!read_STI_uint16(buffer, lib, &out->burn_threshold)) return false;
    if (!read_STI_uint16(buffer, lib, &out->explosion_delay_s)) return false;
    if (!read_STI_int8(buffer, lib, &out->disable_interaction_on_destruction)) return false;
    buffer->skip(buffer, 1);
    if (!read_STI_uint16(buffer, lib, &out->burn_duration_s)) return false;
    if (!read_STI_uint16(buffer, lib, &out->vulnerable_duration_s)) return false;
    if (!read_STI_int32(buffer, lib, &out->explosion_threshold)) return false;
    if (!read_STI_int32(buffer, lib, &out->npc_explosion_threshold)) return false;
    if (!read_STI_int32(buffer, lib, &out->vulnerable_explosion_threshold)) return false;
    if (!read_STI_int32(buffer, lib, &out->impact_deform_threshold)) return false;
    if (!read_STI_int32(buffer, lib, &out->weapon_deform_threshold)) return false;
    if (!read_DynamicArray_PartDamageType(buffer, lib, &out->part_damage_types)) return false;
    return true;
}
