static bool read_GSNode(Buffer* buffer, STI_TypeLibrary* lib, GSNode* out) {
    if (!read_STI_uint32(buffer, lib, &out->Class)) return false;
    buffer->skip(buffer, 4);
    assert(false && "Pointers are not supported yet");
 // Unknown how pointers work
    buffer->skip(buffer, 8);
    if (!read_GSDataSet(buffer, lib, &out->DataSet)) return false;
    return true;
}
static void free_GSNode(GSNode* obj, STI_TypeLibrary* lib) {
    assert(false && "Pointers are not supported yet");
 // Unknown how pointers work
    free_GSDataSet(&obj->DataSet, lib);
}
static void print_GSNode(const GSNode* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "GSNode {\n");
    indent++;
    fprintf(handle, "%*s%s = ", indent * 4, "", "Class");
    print_STI_uint32(&obj->Class, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "Function");
    assert(false && "Pointers are not supported yet");
 // Unknown how pointers work
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "DataSet");
    print_GSDataSet(&obj->DataSet, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s}", (indent - 1)*4, "");
}
