static bool read_Rudder(Buffer* buffer, STI_TypeLibrary* lib, Rudder* out) {
    if (!read_STI_String(buffer, lib, &out->name)) return false;
    buffer->skip(buffer, -8);
    if (!read_HashString(buffer, lib, &out->physics_component_name)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->hinge_point[i])) return false;
    }
    if (!read_EulerAngles(buffer, lib, &out->hinge_angles)) return false;
    if (!read_Spline20(buffer, lib, &out->zero_angle_deg_vs_speed_kph)) return false;
    if (!read_STI_float32(buffer, lib, &out->distance_to_hinge)) return false;
    if (!read_STI_float32(buffer, lib, &out->turn_steering_factor)) return false;
    if (!read_STI_float32(buffer, lib, &out->pitch_steering_factor)) return false;
    if (!read_STI_float32(buffer, lib, &out->roll_steering_factor)) return false;
    if (!read_STI_float32(buffer, lib, &out->min_angle_deg)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_angle_deg)) return false;
    if (!read_STI_float32(buffer, lib, &out->air_density)) return false;
    if (!read_STI_float32(buffer, lib, &out->frontal_area)) return false;
    if (!read_STI_float32(buffer, lib, &out->drag_coefficient)) return false;
    if (!read_STI_float32(buffer, lib, &out->lift_coefficient)) return false;
    buffer->skip(buffer, 4);
    return true;
}
static void free_Rudder(Rudder* obj, STI_TypeLibrary* lib) {
    free_HashString(&obj->physics_component_name, lib);
    free_EulerAngles(&obj->hinge_angles, lib);
    free_Spline20(&obj->zero_angle_deg_vs_speed_kph, lib);
}
