static bool read_HairConstants(Buffer* buffer, STI_TypeLibrary* lib, HairConstants* out) {
    if (!read_STI_float32(buffer, lib, &out->SpecularGloss)) return false;
    if (!read_STI_float32(buffer, lib, &out->TransmissionIntensity)) return false;
    if (!read_STI_float32(buffer, lib, &out->SpecularFresnel)) return false;
    if (!read_STI_float32(buffer, lib, &out->DiffuseWrap)) return false;
    if (!read_STI_float32(buffer, lib, &out->DiffuseRoughness)) return false;
    if (!read_STI_float32(buffer, lib, &out->AnisotropicStrength)) return false;
    if (!read_STI_float32(buffer, lib, &out->AnisotropicX)) return false;
    if (!read_STI_float32(buffer, lib, &out->AnisotropicY)) return false;
    if (!read_STI_float32(buffer, lib, &out->RimStrength)) return false;
    if (!read_STI_float32(buffer, lib, &out->RingStrength)) return false;
    if (!read_STI_float32(buffer, lib, &out->RingAngle)) return false;
    if (!read_STI_float32(buffer, lib, &out->RingOffset)) return false;
{
        uint16 bitfield_value = 0;
        if (!read_STI_uint16(buffer, lib, &bitfield_value)) return false;
        out->DoubleSided = (bitfield_value >> 0) & 0x1;
        out->AlphaTest = (bitfield_value >> 1) & 0x1;
        out->AlphaBlending = (bitfield_value >> 2) & 0x1;
        out->UseColorMask = (bitfield_value >> 3) & 0x1;
}
    buffer->skip(buffer, 2);
    return true;
}
