static bool read_DynamicArray_RivalMissionComplete(Buffer* buffer, STI_TypeLibrary* lib, DynamicArray_RivalMissionComplete* out) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!read_STI_uint32(buffer, lib, &offset)) return false;
    if (!read_STI_uint32(buffer, lib, &unk0)) return false;
    if (!read_STI_uint32(buffer, lib, &count)) return false;
    if (!read_STI_uint32(buffer, lib, &unk1)) return false;
    DA_init(out, RivalMissionComplete, count);
    if (count>0) {
        int64 original_offset = 0;
        if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
        if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
        for (uint32 i = 0; i < count; ++i) {
            if (!read_RivalMissionComplete(buffer, lib, &out->items[i])) return false;
        }
        out->count = count;
        if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}
static void free_DynamicArray_RivalMissionComplete(DynamicArray_RivalMissionComplete* obj, STI_TypeLibrary* lib) {
    for (uint32 i = 0; i < obj->count; ++i) {
        free_RivalMissionComplete(&obj->items[i], lib);
    }
    DA_free(obj);
}
static void print_DynamicArray_RivalMissionComplete(const DynamicArray_RivalMissionComplete* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "DynamicArray_RivalMissionComplete {\n");
    indent++;
    if (obj->count>50) {
        fprintf(handle, "%*s", indent * 4, "");
        print_RivalMissionComplete(&obj->items[0], lib, handle, indent + 1);
        fprintf(handle, "\n%*s...\n%*s", indent * 4, "", indent * 4, "");
        print_RivalMissionComplete(&obj->items[obj->count-1], lib, handle, indent+1);
        fprintf(handle, "\n");
    } else {
        fprintf(handle, "%*s", indent*4, "");
        for (uint32 i = 0; i < obj->count; ++i) {
            print_RivalMissionComplete(&obj->items[i], lib, handle, indent+1);
            if(i < obj->count-1){
                fprintf(handle,", \n%*s", indent*4, "");
            }
        }
        fprintf(handle, "\n");
    }
    fprintf(handle, "%*s}", (indent - 1) * 4, "");
}
static bool read_ProfileSaveData4(Buffer* buffer, STI_TypeLibrary* lib, ProfileSaveData4* out) {
    if (!read_DynamicArray_STI_uint64(buffer, lib, &out->Collectables)) return false;
    if (!read_DynamicArray_STI_uint32(buffer, lib, &out->EmotesUnlocked)) return false;
    for (uint32 i = 0; i < 8; ++i) {
        if (!read_STI_uint32(buffer, lib, &out->EmoteSlots[i])) return false;
    }
    if (!read_STI_uint64(buffer, lib, &out->TrackingId)) return false;
    if (!read_DynamicArray_STI_int32(buffer, lib, &out->Settings)) return false;
    if (!read_DynamicArray_STI_uint32(buffer, lib, &out->CompletedBounties)) return false;
    if (!read_STI_int64(buffer, lib, &out->LastLogin)) return false;
{
        uint8 bitfield_value = 0;
        if (!read_STI_uint8(buffer, lib, &bitfield_value)) return false;
        out->SocialDisabled = (bitfield_value >> 0) & 0x1;
}
    if (!read_STI_uint8(buffer, lib, &out->VehiclePreferedCameraThirdPerson)) return false;
{
        uint8 bitfield_value = 0;
        if (!read_STI_uint8(buffer, lib, &bitfield_value)) return false;
        out->TrackingEnabled = (bitfield_value >> 0) & 0x1;
        out->ShownTrackingOptIn = (bitfield_value >> 1) & 0x1;
        out->CrashReportingEnabled = (bitfield_value >> 2) & 0x1;
        out->ShownCrashReportingEnabledOptIn = (bitfield_value >> 3) & 0x1;
}
    buffer->skip(buffer, 5);
    if (!read_DynamicArray_ResourceStorageItem(buffer, lib, &out->ResourceStorage)) return false;
    if (!read_DynamicArray_OwnedEquipment1(buffer, lib, &out->SafehouseStorage)) return false;
    if (!read_STI_uint8(buffer, lib, &out->SafehouseStorageSizeColumns)) return false;
    if (!read_STI_uint8(buffer, lib, &out->SafehouseStorageSizeRows)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_uint32(buffer, lib, &out->FixVersion)) return false;
    return true;
}
static void free_ProfileSaveData4(ProfileSaveData4* obj, STI_TypeLibrary* lib) {
    free_DynamicArray_STI_uint64(&obj->Collectables, lib);
    free_DynamicArray_STI_uint32(&obj->EmotesUnlocked, lib);
    free_DynamicArray_STI_int32(&obj->Settings, lib);
    free_DynamicArray_STI_uint32(&obj->CompletedBounties, lib);
    free_DynamicArray_ResourceStorageItem(&obj->ResourceStorage, lib);
    free_DynamicArray_OwnedEquipment1(&obj->SafehouseStorage, lib);
}
