    free_DynamicArray_FogOfWar(&obj->FogOfWar, lib);
    free_DynamicArray_LocationState(&obj->Locations, lib);
    free_DynamicArray_CodexInfo(&obj->CodexInfos, lib);
    free_DynamicArray_ReseveIconInfo(&obj->PlayerFoundIcons, lib);
