static bool read_CollectibleInfo(Buffer* buffer, STI_TypeLibrary* lib, CollectibleInfo* out) {
    if (!read_STI_uint64(buffer, lib, &out->ID)) return false;
    if (!read_STI_String(buffer, lib, &out->Name)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_int8(buffer, lib, &out->Type)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_uint32(buffer, lib, &out->ContentKey)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Position[i])) return false;
    }
    buffer->skip(buffer, 4);
    return true;
}
