static bool read_PointPartConstraint(Buffer* buffer, STI_TypeLibrary* lib, PointPartConstraint* out) {
    if (!read_HashString(buffer, lib, &out->source_part)) return false;
    if (!read_HashString(buffer, lib, &out->target_part)) return false;
    if (!read_STI_int8(buffer, lib, &out->source_part_index)) return false;
    if (!read_STI_int8(buffer, lib, &out->target_part_index)) return false;
    buffer->skip(buffer, 2);
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->translation_offset[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->constrained_translation_axes[i])) return false;
    }
    buffer->skip(buffer, 4);
    return true;
}
