static bool read_EffectRTSystem(Buffer* buffer, STI_TypeLibrary* lib, EffectRTSystem* out) {
    if (!read_DynamicArray_EffectRTEmitterTemplate(buffer, lib, &out->EmitterTemplates)) return false;
    if (!read_DynamicArray_EffectRTEmitter(buffer, lib, &out->Emitters)) return false;
    if (!read_DynamicArray_EffectRTModifier(buffer, lib, &out->Modifiers)) return false;
    if (!read_DynamicArray_EffectRTTimeline(buffer, lib, &out->Timelines)) return false;
    if (!read_DynamicArray_EffectRTInstantiator(buffer, lib, &out->Instantiators)) return false;
    if (!read_DynamicArray_EffectRTSpecialEffect(buffer, lib, &out->SpecialEffects)) return false;
    if (!read_DynamicArray_EffectRTParamHandler(buffer, lib, &out->ParamHandler)) return false;
    if (!read_DynamicArray_STI_float32(buffer, lib, &out->Params)) return false;
    if (!read_EffectRTOutputBufferDescriptor(buffer, lib, &out->OutputBufferDescriptor)) return false;
    if (!read_DynamicArray_EffectRTLocalParam(buffer, lib, &out->NamedParameters)) return false;
    if (!read_STI_uint32(buffer, lib, &out->NamedParametersSize)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_StringHash_48c5294d_4(buffer, lib, &out->Dependencies)) return false;
    if (!read_DynamicArray_STI_float32(buffer, lib, &out->Properties)) return false;
    return true;
}
