    if (!read_STI_float32(buffer, lib, &out->y_min)) return false;
    if (!read_STI_float32(buffer, lib, &out->y_max)) return false;
    if (!read_STI_int8(buffer, lib, &out->number_of_control_points)) return false;
    if (!read_STI_int8(buffer, lib, &out->interpolation_type)) return false;
    buffer->skip(buffer, 2);
