static bool read_CameraCollisionParams(Buffer* buffer, STI_TypeLibrary* lib, CameraCollisionParams* out) {
    if (!read_STI_uint8(buffer, lib, &out->BypassModifier)) return false;
    if (!read_STI_uint8(buffer, lib, &out->DrawDebug)) return false;
    buffer->skip(buffer, 2);
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->CollisionResponseOffset[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->Radius)) return false;
    if (!read_STI_float32(buffer, lib, &out->PassthroughRadius)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxCameraPassthroughThickness)) return false;
    if (!read_STI_uint8(buffer, lib, &out->CollideCharacter)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_float32(buffer, lib, &out->ExtensionMaxVelocity)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxDistancePushVelocity)) return false;
    if (!read_STI_float32(buffer, lib, &out->MovementCastAhead)) return false;
    if (!read_STI_float32(buffer, lib, &out->AngularCastAhead)) return false;
    if (!read_STI_float32(buffer, lib, &out->MinCollisionDist)) return false;
    if (!read_STI_float32(buffer, lib, &out->CameraPlaneMargin)) return false;
    if (!read_STI_float32(buffer, lib, &out->CameraPushMargin)) return false;
    if (!read_CameraSpline5(buffer, lib, &out->DistanceToOpacitySpline)) return false;
    if (!read_STI_uint8(buffer, lib, &out->IgnoreOffsetDistanceChange)) return false;
    if (!read_STI_uint8(buffer, lib, &out->IgnorePlayerVehicle)) return false;
    if (!read_STI_uint8(buffer, lib, &out->KeepAboveWater)) return false;
    if (!read_STI_uint8(buffer, lib, &out->DisableClosestProximityCollision)) return false;
    if (!read_STI_uint8(buffer, lib, &out->CollisionResponseUprightViewAligned)) return false;
    buffer->skip(buffer, 3);
    return true;
}
