static bool read_EffectRTTimeline(Buffer* buffer, STI_TypeLibrary* lib, EffectRTTimeline* out) {
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_int8(buffer, lib, &out->ControlPointsY[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->StartX[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->EndX[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->XScaleRecip[i])) return false;
    }
    return true;
}
