static bool read_LightInfo(Buffer* buffer, STI_TypeLibrary* lib, LightInfo* out) {
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Position[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->Diffuse[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->Radius)) return false;
    if (!read_STI_uint8(buffer, lib, &out->HasDistantLod)) return false;
    buffer->skip(buffer, 7);
    if (!read_STI_uint64(buffer, lib, &out->ObjectID)) return false;
    if (!read_STI_uint32(buffer, lib, &out->Ordinal)) return false;
    if (!read_STI_uint16(buffer, lib, &out->CellIndex)) return false;
    buffer->skip(buffer, 2);
    return true;
}
