static bool read_PfxSimplePartInstance(Buffer* buffer, STI_TypeLibrary* lib, PfxSimplePartInstance* out) {
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_float32(buffer, lib, &out->breakable_space_transform[i])) return false;
    }
    if (!read_STI_String(buffer, lib, &out->collision_path)) return false;
    buffer->skip(buffer, 16);
    return true;
}
static void free_PfxSimplePartInstance(PfxSimplePartInstance* obj, STI_TypeLibrary* lib) {
}
static void print_PfxSimplePartInstance(const PfxSimplePartInstance* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "PfxSimplePartInstance {\n");
    indent++;
    fprintf(handle, "%*s%s = ", indent * 4, "", "breakable_space_transform");
    fprintf(handle, "{\n%*s", (indent+1)*4, "");
    for (uint32 i = 0; i < 16; ++i) {
        print_STI_float32(&obj->breakable_space_transform[i], lib, handle, indent+1);
        if(i < 15){
            fprintf(handle,", \n%*s", (indent+1)*4, "");
        }
    }
    fprintf(handle, "\n%*s}", (indent+1)*4, "");
    fprintf(handle, "\n");
    fprintf(handle, "%*s%s = ", indent * 4, "", "collision_path");
    print_STI_String(&obj->collision_path, lib, handle, indent + 1);
    fprintf(handle, "\n");
    fprintf(handle, "%*s}", (indent - 1)*4, "");
}
