static bool read_Value(Buffer* buffer, STI_TypeLibrary* lib, Value* out) {
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->NameHash)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->TypeHash)) return false;
    if (!read_STI_int32(buffer, lib, &out->DataInt)) return false;
    if (!read_STI_float32(buffer, lib, &out->DataFloat)) return false;
    uint32 string_offset = 0;
    uint32 string_size = 0;
    if (!read_STI_int32(buffer, lib, &string_offset)) return false;
    if (!read_STI_int32(buffer, lib, &string_size)) return false;
    uint64 current_offset = 0;
    buffer->get_position(buffer, &current_offset);
    buffer->set_position(buffer, string_offset, BUFFER_ORIGIN_START);
    if (!read_STI_String(buffer, lib, &out->DataString)) return false;
    buffer->set_position(buffer, current_offset, BUFFER_ORIGIN_START);
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->DataStringHash)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DataVector3f[i])) return false;
    }
    return true;
}
