static bool read_IKChain(Buffer* buffer, STI_TypeLibrary* lib, IKChain* out) {
    if (!read_HashString(buffer, lib, &out->attachment_part)) return false;
    if (!read_STI_int8(buffer, lib, &out->attachment_part_index)) return false;
    buffer->skip(buffer, 7);
    if (!read_HashString(buffer, lib, &out->root_part)) return false;
    if (!read_STI_int8(buffer, lib, &out->root_part_index)) return false;
    buffer->skip(buffer, 7);
    if (!read_HashString(buffer, lib, &out->mid_part)) return false;
    if (!read_STI_int8(buffer, lib, &out->mid_part_index)) return false;
    buffer->skip(buffer, 7);
    if (!read_HashString(buffer, lib, &out->effector_part)) return false;
    if (!read_STI_int8(buffer, lib, &out->effector_part_index)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_float32(buffer, lib, &out->root_to_mid_length)) return false;
    if (!read_STI_float32(buffer, lib, &out->mid_to_effector_length)) return false;
    buffer->skip(buffer, 4);
    return true;
}
static void free_IKChain(IKChain* obj, STI_TypeLibrary* lib) {
    free_HashString(&obj->attachment_part, lib);
    free_HashString(&obj->root_part, lib);
    free_HashString(&obj->mid_part, lib);
    free_HashString(&obj->effector_part, lib);
}
