static bool read_CharacterAirMovementSettings(Buffer* buffer, STI_TypeLibrary* lib, CharacterAirMovementSettings* out) {
    if (!read_STI_float32(buffer, lib, &out->Gravity)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxVelocity)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxVelocityXZ)) return false;
    if (!read_STI_float32(buffer, lib, &out->ClampVelocitySpeed)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Lift[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DragX[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DragY[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DragZ[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LiftPoint[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->PitchLimit[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->YawSteerAmount)) return false;
    if (!read_STI_uint32(buffer, lib, &out->DrawDebugLines)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->RotateCharYawToVelocity)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->RotateCharPitchToVelocity)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->PitchInputSpring)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->YawInputSpring)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->RollInputSpring)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->XInputYawPitchRollAmount[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->YInputYawPitchRollAmount[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->XLookYawPitchRollAmount[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->YLookYawPitchRollAmount[i])) return false;
    }
    if (!read_CharacterSpring(buffer, lib, &out->RotateCharYawToSlingshot)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->PersistYawPitchRoll[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->CenterYawPitchRoll[i])) return false;
    }
    if (!read_CharacterSpring(buffer, lib, &out->LiftInputSpring)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->DragInputSpring)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->AnimInputSpringX)) return false;
    if (!read_CharacterSpring(buffer, lib, &out->AnimInputSpringY)) return false;
    if (!read_STI_float32(buffer, lib, &out->NearGroundLiftDistance)) return false;
    if (!read_STI_float32(buffer, lib, &out->NearGroundMaxLift)) return false;
    if (!read_STI_float32(buffer, lib, &out->NearGroundLiftExponent)) return false;
    if (!read_STI_float32(buffer, lib, &out->NearGroundLiftDecayMax)) return false;
    if (!read_STI_float32(buffer, lib, &out->NearGroundLiftDecayMultiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->NearGroundLiftRecoverRate)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerDeadZone[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerMaxSpeed[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->LookSteerMaxYaw)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerMaxPitch[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerExponential[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerAimingDeadZone[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerAimingMaxSpeed[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->LookSteerAimingMaxYaw)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerAimingMaxPitch[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->LookSteerAimingExponential[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SlingshotPitchAdjust)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotExtraLift)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotDirectAccel)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotForwardAccel)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotMaxSpeedAdjust)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->SlingshotDragXYZAdjust[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SlingshotBreakPitch)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotBreakYawStart)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotBreakYawEnd)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotBreakYawBlendTime)) return false;
    if (!read_STI_float32(buffer, lib, &out->SlingshotBreakDistance)) return false;
    if (!read_CharacterRetractSShotSettings(buffer, lib, &out->RetractSlingshotSettings)) return false;
    return true;
}
static void free_CharacterAirMovementSettings(CharacterAirMovementSettings* obj, STI_TypeLibrary* lib) {
    free_CharacterSpring(&obj->RotateCharYawToVelocity, lib);
    free_CharacterSpring(&obj->RotateCharPitchToVelocity, lib);
    free_CharacterSpring(&obj->PitchInputSpring, lib);
    free_CharacterSpring(&obj->YawInputSpring, lib);
    free_CharacterSpring(&obj->RollInputSpring, lib);
    free_CharacterSpring(&obj->RotateCharYawToSlingshot, lib);
    free_CharacterSpring(&obj->LiftInputSpring, lib);
    free_CharacterSpring(&obj->DragInputSpring, lib);
    free_CharacterSpring(&obj->AnimInputSpringX, lib);
    free_CharacterSpring(&obj->AnimInputSpringY, lib);
    free_CharacterRetractSShotSettings(&obj->RetractSlingshotSettings, lib);
}
