static bool read_CarPaintMMStaticConstants(Buffer* buffer, STI_TypeLibrary* lib, CarPaintMMStaticConstants* out) {
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->SpecularGloss[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Metallic[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->ClearCoat[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Emissive[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DiffuseWrap[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DirtParams[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DirtColor[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DecalWidth[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DamageBlend[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Damage[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Decal1Color[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SupportDecals)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Decal2Color[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SupportDmgBlend)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Decal3Color[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SupportLayered)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Decal4Color[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SupportOverlay)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DecalBlend[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SupportRotating)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DamageColor[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SupportDirt)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DirtBlend[i])) return false;
    }
    if (!read_STI_float32(buffer, lib, &out->SupportSoftTint)) return false;
    return true;
}
