static bool read_VegetationWorld(Buffer* buffer, STI_TypeLibrary* lib, VegetationWorld* out) {
    if (!read_VegetationLayers(buffer, lib, &out->VegetationLayers)) return false;
    if (!read_DynamicArray_VegetationZone(buffer, lib, &out->VegetationZones)) return false;
    if (!read_DynamicArray_VegetationObject(buffer, lib, &out->VegetationObjects)) return false;
    if (!read_VegetationZone(buffer, lib, &out->DefaultVegetationZone)) return false;
    if (!read_DynamicArray_VegetationIndex(buffer, lib, &out->VegetationIndex)) return false;
    if (!read_STI_String(buffer, lib, &out->BillboardAtlasDiffuse)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_String(buffer, lib, &out->BillboardAtlasNormal)) return false;
    buffer->skip(buffer, -8);
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->WorldSize[i])) return false;
    }
    buffer->skip(buffer, 4);
    if (!read_ImpostorCollection(buffer, lib, &out->ImpostorCollection)) return false;
    return true;
}
static void free_VegetationWorld(VegetationWorld* obj, STI_TypeLibrary* lib) {
    free_VegetationLayers(&obj->VegetationLayers, lib);
    free_DynamicArray_VegetationZone(&obj->VegetationZones, lib);
    free_DynamicArray_VegetationObject(&obj->VegetationObjects, lib);
    free_VegetationZone(&obj->DefaultVegetationZone, lib);
    free_DynamicArray_VegetationIndex(&obj->VegetationIndex, lib);
    free_ImpostorCollection(&obj->ImpostorCollection, lib);
}
