static bool read_LocalAngleLimitsModifierParams(Buffer* buffer, STI_TypeLibrary* lib, LocalAngleLimitsModifierParams* out) {
    if (!read_STI_uint8(buffer, lib, &out->BypassModifier)) return false;
    if (!read_STI_uint8(buffer, lib, &out->DisablePitchLimits)) return false;
    buffer->skip(buffer, 2);
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->PitchLimit[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->PitchLimitSmoothing[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->DisableYawLimits)) return false;
    buffer->skip(buffer, 3);
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->YawLimit[i])) return false;
    }
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->YawLimitSmoothing[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->UsePlayerCharacterRootPitch)) return false;
    buffer->skip(buffer, 3);
    return true;
}
