static bool read_HunterMission(Buffer* buffer, STI_TypeLibrary* lib, HunterMission* out) {
    if (!read_STI_int32(buffer, lib, &out->Id)) return false;
    if (!read_STI_uint8(buffer, lib, &out->Enabled)) return false;
    if (!read_STI_uint8(buffer, lib, &out->Required)) return false;
    if (!read_STI_uint8(buffer, lib, &out->Visible)) return false;
    buffer->skip(buffer, 1);
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->Type)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->Name)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->NameShort)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->AchievementId)) return false;
    if (!read_StringHash_99cfa095_6(buffer, lib, &out->ActivationEvent)) return false;
    if (!read_StringHash_99cfa095_6(buffer, lib, &out->CancelEvent)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_SpecificEvent(buffer, lib, &out->SpecificCancelEvents)) return false;
    if (!read_STI_int32(buffer, lib, &out->TimeLimit)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->Summary)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->Description)) return false;
    if (!read_StringHash_99cfa095_6(buffer, lib, &out->Reward)) return false;
    buffer->skip(buffer, 6);
    if (!read_DynamicArray_StringHash_48c5294d_4(buffer, lib, &out->Locations)) return false;
    if (!read_DynamicArray_StringHash_48c5294d_4(buffer, lib, &out->Regions)) return false;
    if (!read_STI_uint64(buffer, lib, &out->WarboardRegion)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->WarboardSubType)) return false;
    buffer->skip(buffer, 4);
    if (!read_STI_String(buffer, lib, &out->Banner)) return false;
    buffer->skip(buffer, -8);
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->Character)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->ContentKey)) return false;
    if (!read_DynamicArray_STI_int32(buffer, lib, &out->DependenciesRequired)) return false;
    if (!read_DynamicArray_STI_int32(buffer, lib, &out->DependenciesOptional)) return false;
    if (!read_STI_uint32(buffer, lib, &out->ContentHash)) return false;
    if (!read_STI_uint8(buffer, lib, &out->CarryOver)) return false;
    if (!read_STI_uint8(buffer, lib, &out->CanCancelCompleted)) return false;
    buffer->skip(buffer, 2);
    if (!read_DynamicArray_HunterMissionObjective(buffer, lib, &out->Objectives)) return false;
    if (!read_DynamicArray_HunterMissionEvent(buffer, lib, &out->Events)) return false;
    if (!read_DynamicArray_HunterMissionAttachment(buffer, lib, &out->Attachments)) return false;
    return true;
}
