static bool read_VegetationSystemInstance(Buffer* buffer, STI_TypeLibrary* lib, VegetationSystemInstance* out) {
    if (!read_STI_uint16(buffer, lib, &out->X)) return false;
    if (!read_STI_uint16(buffer, lib, &out->Z)) return false;
{
        uint32 bitfield_value = 0;
        if (!read_STI_uint32(buffer, lib, &bitfield_value)) return false;
        out->Y = (bitfield_value >> 0) & 0xFFFFFF;
        out->ZoneIndex = (bitfield_value >> 24) & 0x3F;
        out->IsPlanted = (bitfield_value >> 30) & 0x1;
        out->IsDestroyed = (bitfield_value >> 31) & 0x1;
}
    buffer->skip(buffer, 4);
    if (!read_STI_uint32(buffer, lib, &out->Rotation)) return false;
    if (!read_STI_uint8(buffer, lib, &out->Color_R)) return false;
    if (!read_STI_uint8(buffer, lib, &out->Color_G)) return false;
    if (!read_STI_uint8(buffer, lib, &out->Color_B)) return false;
    buffer->skip(buffer, 1);
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->NameHash)) return false;
    return true;
}
