static bool read_WorldAudioZone(Buffer* buffer, STI_TypeLibrary* lib, WorldAudioZone* out) {
    if (!read_STI_String(buffer, lib, &out->Name)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_String(buffer, lib, &out->LoopGuid)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_String(buffer, lib, &out->DetailGuid)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_float32(buffer, lib, &out->SortBias)) return false;
    if (!read_STI_float32(buffer, lib, &out->DepthRadius)) return false;
    if (!read_STI_float32(buffer, lib, &out->Radius)) return false;
    if (!read_STI_float32(buffer, lib, &out->VolumeSumBias)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxDistance)) return false;
    if (!read_STI_float32(buffer, lib, &out->Linearity)) return false;
    if (!read_STI_float32(buffer, lib, &out->EnergyRadius)) return false;
    if (!read_STI_float32(buffer, lib, &out->DetailDensity)) return false;
    if (!read_STI_float32(buffer, lib, &out->DetailRadius)) return false;
    if (!read_STI_float32(buffer, lib, &out->DetailVolumeSumBias)) return false;
    if (!read_STI_float32(buffer, lib, &out->DetailMaxDistance)) return false;
    if (!read_STI_float32(buffer, lib, &out->DetailLinearity)) return false;
    if (!read_STI_float32(buffer, lib, &out->DetailEnergyRadius)) return false;
    if (!read_STI_float32(buffer, lib, &out->FadeOutTime)) return false;
    if (!read_STI_float32(buffer, lib, &out->FadeInTime)) return false;
    if (!read_STI_float32(buffer, lib, &out->ZoneHeight)) return false;
    if (!read_STI_uint32(buffer, lib, &out->ZoneType)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->DebugColor[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->IsAllowedUnderwater)) return false;
    buffer->skip(buffer, 7);
    return true;
}
