static bool read_DynamicArray_HunterMissionEvent(Buffer* buffer, STI_TypeLibrary* lib, DynamicArray_HunterMissionEvent* out) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!read_STI_uint32(buffer, lib, &offset)) return false;
    if (!read_STI_uint32(buffer, lib, &unk0)) return false;
    if (!read_STI_uint32(buffer, lib, &count)) return false;
    if (!read_STI_uint32(buffer, lib, &unk1)) return false;
    DA_init(out, HunterMissionEvent, count);
    if (count>0) {
        int64 original_offset = 0;
        if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
        if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
        for (uint32 i = 0; i < count; ++i) {
            if (!read_HunterMissionEvent(buffer, lib, &out->items[i])) return false;
        }
        out->count = count;
        if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}
static void free_DynamicArray_HunterMissionEvent(DynamicArray_HunterMissionEvent* obj, STI_TypeLibrary* lib) {
    for (uint32 i = 0; i < obj->count; ++i) {
        free_HunterMissionEvent(&obj->items[i], lib);
    }
    DA_free(obj);
}
static void print_DynamicArray_HunterMissionEvent(const DynamicArray_HunterMissionEvent* obj, STI_TypeLibrary* lib, FILE* handle, uint32 indent) {
    fprintf(handle, "DynamicArray_HunterMissionEvent {\n");
    indent++;
    if (obj->count>50) {
        fprintf(handle, "%*s", indent * 4, "");
        print_HunterMissionEvent(&obj->items[0], lib, handle, indent + 1);
        fprintf(handle, "\n%*s...\n%*s", indent * 4, "", indent * 4, "");
        print_HunterMissionEvent(&obj->items[obj->count-1], lib, handle, indent+1);
        fprintf(handle, "\n");
    } else {
        fprintf(handle, "%*s", indent*4, "");
        for (uint32 i = 0; i < obj->count; ++i) {
            print_HunterMissionEvent(&obj->items[i], lib, handle, indent+1);
            if(i < obj->count-1){
                fprintf(handle,", \n%*s", indent*4, "");
            }
        }
        fprintf(handle, "\n");
    }
    fprintf(handle, "%*s}", (indent - 1) * 4, "");
}
static bool read_VehicleMisc_2(Buffer* buffer, STI_TypeLibrary* lib, VehicleMisc_2* out) {
    if (!read_STI_float32(buffer, lib, &out->open_door_duration_s)) return false;
    if (!read_STI_float32(buffer, lib, &out->close_door_duration_s)) return false;
    if (!read_DynamicArray_VehicleDoor(buffer, lib, &out->doors)) return false;
    if (!read_STI_float32(buffer, lib, &out->official_top_speed)) return false;
    if (!read_STI_float32(buffer, lib, &out->full_nitro_refill_time)) return false;
    if (!read_STI_float32(buffer, lib, &out->nitro_refill_min_speed_kph)) return false;
    if (!read_STI_float32(buffer, lib, &out->full_nitro_use_time)) return false;
    if (!read_STI_float32(buffer, lib, &out->full_nitro_use_time_upgraded)) return false;
    if (!read_STI_float32(buffer, lib, &out->turbo_jump_cooldown)) return false;
    if (!read_STI_float32(buffer, lib, &out->turbo_jump_cooldown_upgraded)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_landing_speed_kmph)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_take_off_speed_kmph)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_tilt_to_land_deg)) return false;
    if (!read_STI_float32(buffer, lib, &out->min_damage_speed_kph)) return false;
    if (!read_STI_float32(buffer, lib, &out->max_damage_speed_kph)) return false;
    if (!read_STI_int32(buffer, lib, &out->damage_at_min_speed)) return false;
    if (!read_STI_int32(buffer, lib, &out->damage_at_max_speed)) return false;
    if (!read_STI_float32(buffer, lib, &out->impulse_resistance)) return false;
    if (!read_MotorbikeFuelSettings(buffer, lib, &out->fuel_settings)) return false;
    if (!read_PatchProvision(buffer, lib, &out->patch_provision)) return false;
    buffer->skip(buffer, 4);
    return true;
}
