static bool read_GeneralMeshConstants(Buffer* buffer, STI_TypeLibrary* lib, GeneralMeshConstants* out) {
    if (!read_STI_uint32(buffer, lib, &out->PristineIndexCount)) return false;
{
        uint8 bitfield_value = 0;
        if (!read_STI_uint8(buffer, lib, &bitfield_value)) return false;
        out->IsDestructionMesh = (bitfield_value >> 0) & 0x1;
        out->IsSkinnedMesh = (bitfield_value >> 1) & 0x1;
}
    buffer->skip(buffer, 3);
    return true;
}
