static bool read_ShaderRules(Buffer* buffer, STI_TypeLibrary* lib, ShaderRules* out) {
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->NameHash)) return false;
    if (!read_StringHash_48c5294d_4(buffer, lib, &out->AudioZone)) return false;
    if (!read_STI_uint8(buffer, lib, &out->TopographyIndex)) return false;
    buffer->skip(buffer, 3);
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_float32(buffer, lib, &out->Rotation[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->RotationIndex)) return false;
    buffer->skip(buffer, 3);
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_TerrainMaterial(buffer, lib, &out->VariationMaterials[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->VariationIndex)) return false;
    if (!read_STI_uint8(buffer, lib, &out->InvertVariation)) return false;
    if (!read_STI_uint8(buffer, lib, &out->TransitionSlot)) return false;
    buffer->skip(buffer, 1);
    if (!read_STI_float32(buffer, lib, &out->SlotBlendFactor)) return false;
    if (!read_STI_float32(buffer, lib, &out->NormalDetailBalance)) return false;
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_TerrainMaterial(buffer, lib, &out->PrimitiveMaterials[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->VariationSlotCenters[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->NormalSlotCenters[i])) return false;
    }
    for (uint32 i = 0; i < 4; ++i) {
        if (!read_STI_float32(buffer, lib, &out->PrimitiveSlotCenters[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->ColorNear[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->ColorMid[i])) return false;
    }
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->DebugColor[i])) return false;
    }
    if (!read_STI_uint8(buffer, lib, &out->ProjectionType)) return false;
    buffer->skip(buffer, 2);
    if (!read_STI_float32(buffer, lib, &out->DisplacementScale)) return false;
    if (!read_STI_float32(buffer, lib, &out->DisplacementBias)) return false;
    if (!read_STI_uint8(buffer, lib, &out->DisplacementMip)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_float32(buffer, lib, &out->BlendScale)) return false;
    if (!read_STI_float32(buffer, lib, &out->BlendBias)) return false;
    return true;
}
static void free_ShaderRules(ShaderRules* obj, STI_TypeLibrary* lib) {
    for (uint32 i = 0; i < 4; ++i) {
        free_TerrainMaterial(&obj->VariationMaterials[i], lib);
    }
    for (uint32 i = 0; i < 4; ++i) {
        free_TerrainMaterial(&obj->PrimitiveMaterials[i], lib);
    }
}
