static bool read_FocusDofModifierParams(Buffer* buffer, STI_TypeLibrary* lib, FocusDofModifierParams* out) {
    if (!read_STI_uint8(buffer, lib, &out->BypassModifier)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_float32(buffer, lib, &out->NearRicoToCamFraction)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxNearFocusDifferential)) return false;
    if (!read_STI_uint8(buffer, lib, &out->RespectNearLimitIfNoDirect)) return false;
    buffer->skip(buffer, 3);
    if (!read_STI_float32(buffer, lib, &out->FarMultiplier)) return false;
    if (!read_STI_float32(buffer, lib, &out->MaxFarFocusDifferential)) return false;
    if (!read_STI_uint8(buffer, lib, &out->RespectFarLimitIfNoDirect)) return false;
    buffer->skip(buffer, 3);
    if (!read_CameraSpring(buffer, lib, &out->DistanceSpring)) return false;
    if (!read_CameraSpline5(buffer, lib, &out->RightStickToMaxDof)) return false;
    if (!read_CameraSpring(buffer, lib, &out->MoreBlurSpring)) return false;
    if (!read_CameraSpring(buffer, lib, &out->LessBlurSpring)) return false;
    if (!read_STI_uint8(buffer, lib, &out->RespectWeaponOverride)) return false;
    buffer->skip(buffer, 3);
    return true;
}
