static bool read_StuntArea(Buffer* buffer, STI_TypeLibrary* lib, StuntArea* out) {
    if (!read_STI_String(buffer, lib, &out->name)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_uint32(buffer, lib, &out->name_hash)) return false;
    buffer->skip(buffer, 4);
    if (!read_STI_String(buffer, lib, &out->part_name)) return false;
    buffer->skip(buffer, -8);
    if (!read_STI_uint32(buffer, lib, &out->part_hash)) return false;
    if (!read_STI_uint32(buffer, lib, &out->part_index)) return false;
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_uint32(buffer, lib, &out->deform_points[i])) return false;
    }
    for (uint32 i = 0; i < 16; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->edge_validity[i])) return false;
    }
    if (!read_STI_uint16(buffer, lib, &out->number_of_deform_points)) return false;
    if (!read_STI_uint16(buffer, lib, &out->active)) return false;
    for (uint32 i = 0; i < 48; ++i) {
        if (!read_STI_float32(buffer, lib, &out->vertices3D_local[i])) return false;
    }
    for (uint32 i = 0; i < 42; ++i) {
        if (!read_STI_uint8(buffer, lib, &out->triangle_indices[i])) return false;
    }
    if (!read_STI_uint16(buffer, lib, &out->number_of_triangles)) return false;
    if (!read_AxisAlignedBoundingBox(buffer, lib, &out->bounding_box_local)) return false;
    for (uint32 i = 0; i < 3; ++i) {
        if (!read_STI_float32(buffer, lib, &out->center_local[i])) return false;
    }
    buffer->skip(buffer, 4);
    return true;
}
static void free_StuntArea(StuntArea* obj, STI_TypeLibrary* lib) {
    free_AxisAlignedBoundingBox(&obj->bounding_box_local, lib);
}
