static bool read_WorldSaveData10(Buffer* buffer, STI_TypeLibrary* lib, WorldSaveData10* out) {
    if (!read_DynamicArray_RegionData(buffer, lib, &out->Regions)) return false;
    if (!read_AnimalPopulationsSaveData3(buffer, lib, &out->AnimalPopulations)) return false;
    if (!read_DynamicArray_STI_uint64(buffer, lib, &out->Collectables)) return false;
    if (!read_STI_uint32(buffer, lib, &out->LootSeed)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_FogOfWar(buffer, lib, &out->FogOfWar)) return false;
    if (!read_STI_int32(buffer, lib, &out->ReserveId)) return false;
    buffer->skip(buffer, 4);
    if (!read_DynamicArray_LocationState(buffer, lib, &out->Locations)) return false;
    if (!read_DynamicArray_CodexInfo(buffer, lib, &out->CodexInfos)) return false;
    if (!read_DynamicArray_ReseveIconInfo(buffer, lib, &out->PlayerFoundIcons)) return false;
    if (!read_DynamicArray_StatisticInfo(buffer, lib, &out->Statistics)) return false;
    if (!read_DynamicArray_ContextualHelpInfo(buffer, lib, &out->ContextualHelpInfos)) return false;
    if (!read_STI_uint8(buffer, lib, &out->ContextualHelpActive)) return false;
    buffer->skip(buffer, 7);
    if (!read_DynamicArray_LocationSummarySaveData(buffer, lib, &out->LocationSummaries)) return false;
    if (!read_DynamicArray_RaidSaveData2(buffer, lib, &out->Raids)) return false;
    if (!read_DynamicArray_TimerSaveData1(buffer, lib, &out->Timers)) return false;
    if (!read_DynamicArray_STI_uint64(buffer, lib, &out->PlayerSpawnPoints)) return false;
    if (!read_DynamicArray_RivalRegion1(buffer, lib, &out->RivalRegions)) return false;
    for (uint32 i = 0; i < 2; ++i) {
        if (!read_STI_uint64(buffer, lib, &out->RivalUsedNumbers[i])) return false;
    }
    if (!read_STI_uint32(buffer, lib, &out->DifficultyLevel)) return false;
    if (!read_STI_uint8(buffer, lib, &out->DifficultyScaleByPlayers)) return false;
    buffer->skip(buffer, 3);
    if (!read_DynamicArray_ControlPointSaveData2(buffer, lib, &out->ControlPoints)) return false;
    if (!read_DynamicArray_RivalMissionGroup1(buffer, lib, &out->RivalMissionGroups)) return false;
    return true;
}
